int origBtreeCursorIsLastOnSingle(void *pCur){
  BtCursor *c = C(pCur);
  BtShared *pBt;
  if( !c || !c->pBt ) return 0;
  pBt = c->pBt;
  if( (pBt->openFlags & BTREE_SINGLE)==0 ) return 0;
  return pBt->pCursor==c && c->pNext==0;
}
