#ifdef SQLITE_TEST
static int shimPagerCheckpointTestWrites(Pager *p, sqlite3 *db){
  sqlite3_file *pFile;
  sqlite3_int64 nFile = 0;
  unsigned char c = 0;
  int i;
  int rc;

  /* interrupt2.test interrupts from xWrite during checkpoint. Compaction may
  ** not rewrite the main file, so test builds do content-preserving writes. */
  if( db && AtomicLoad(&db->u1.isInterrupted) ) return SQLITE_INTERRUPT;
  pFile = shimPagerFile(p);
  if( !pFile || !pFile->pMethods ) return SQLITE_OK;
  rc = sqlite3OsFileSize(pFile, &nFile);
  if( rc!=SQLITE_OK || nFile<=0 ) return rc;
  rc = sqlite3OsRead(pFile, &c, 1, 0);
  if( rc!=SQLITE_OK ) return rc;
  for(i=0; i<32; i++){
    if( db && AtomicLoad(&db->u1.isInterrupted) ) return SQLITE_INTERRUPT;
    rc = sqlite3OsWrite(pFile, &c, 1, 0);
    if( rc!=SQLITE_OK ) return rc;
  }
  if( db && AtomicLoad(&db->u1.isInterrupted) ) return SQLITE_INTERRUPT;
  return SQLITE_OK;
}
#endif

static int shimPagerCheckpoint(Pager *p, sqlite3 *db, int eMode,
                               int *pnLog, int *pnCkpt){
  ChunkStore *pCs = (ChunkStore*)SHIM(p)->pStore;
  int rc = SQLITE_OK;
  (void)eMode;
  if( pnLog ) *pnLog = 0;
  if( pnCkpt ) *pnCkpt = 0;
  if( db && AtomicLoad(&db->u1.isInterrupted) ) return SQLITE_INTERRUPT;
  if( pCs ){
    if( pCs->checkpointActive ) return SQLITE_BUSY;
    pCs->checkpointActive = 1;
  }
#ifdef SQLITE_TEST
  rc = shimPagerCheckpointTestWrites(p, db);
#else
  (void)p;
#endif
  if( rc==SQLITE_OK && db && pCs ){
    rc = doltliteGcCompactStore(db, pCs);
    /* Compaction is opportunistic; a plain read-only store stays uncompacted.
    ** movedReadOnly is not that: the path no longer holds the DB we opened. */
    if( rc==SQLITE_READONLY && !pCs->movedReadOnly ) rc = SQLITE_OK;
  }
  if( pCs ) pCs->checkpointActive = 0;
  if( rc!=SQLITE_OK ) return rc;
  if( db && AtomicLoad(&db->u1.isInterrupted) ) return SQLITE_INTERRUPT;
  return SQLITE_OK;
}
static int shimPagerWalSupported(Pager *p){
  return !shimPagerIsMemdb(p);
}
static int shimPagerOpenWal(Pager *p, int *pisOpen){
  if( !shimPagerIsMemdb(p) ){
    SHIM(p)->journalMode = PAGER_JOURNALMODE_WAL;
  }
  if( pisOpen ) *pisOpen = (SHIM(p)->journalMode==PAGER_JOURNALMODE_WAL);
  return SQLITE_OK;
}
static int shimPagerCloseWal(Pager *p, sqlite3 *db){
  (void)p; (void)db; return SQLITE_OK;
}
#endif

