/************** Begin file doltlite_merge_pass1.c ****************************/
#ifdef DOLTLITE_PROLLY

/* #include "doltlite_merge_int.h" */

int mergeAppendReindexName(char ***paz, int *pn, const char *zName){
  char **azNew;
  char *zDup;
  if( !paz ) return SQLITE_OK;
  azNew = sqlite3_realloc(*paz, (*pn+1)*(int)sizeof(char*));
  if( !azNew ) return SQLITE_NOMEM;
  *paz = azNew;
  zDup = sqlite3_mprintf("%s", zName);
  if( !zDup ) return SQLITE_NOMEM;
  (*paz)[(*pn)++] = zDup;
  return SQLITE_OK;
}

static void mergePass1Free(MergePass1Ctx *c){
  sqlite3_free(c->aPatches);
  c->aPatches = 0;
  c->nPatches = c->nPatchesAlloc = 0;
}

static int mergePass1NoteSchemaConflict(
  MergePass1Ctx *c,
  const char *zTable,
  const char *zObject
){
  int added = 0;
  int rc = appendSchemaConflict(
      c->ppConflictTables, c->pnConflictTables,
      zTable ? zTable : "", zObject ? zObject : "", &added);
  if( rc!=SQLITE_OK ) return rc;
  if( added ) (*c->pTotalConflicts)++;
  return SQLITE_OK;
}

static void mergePass1FreeIdxInfo(MergeIndexInfo *aIdxInfo, int nIdxInfo){
  int i;
  if( !aIdxInfo ) return;
  for(i=0; i<nIdxInfo; i++){
    if( aIdxInfo[i].pKeyInfo ){
      sqlite3KeyInfoUnref(aIdxInfo[i].pKeyInfo);
      aIdxInfo[i].pKeyInfo = 0;
    }
  }
  sqlite3_free(aIdxInfo);
}

static int mergePass1SchemaPrefixInfo(
  const char *zAncSql,
  const char *zSideSql,
  int *pbPrefix,
  int *pnAnc,
  int *pnSide,
  int *pnAncRecord
){
  ParsedColumn *aAnc = 0;
  ParsedColumn *aSide = 0;
  int nAnc = 0;
  int nSide = 0;
  int i;
  int rc;

  *pbPrefix = 0;
  *pnAnc = 0;
  *pnSide = 0;
  if( pnAncRecord ) *pnAncRecord = 0;
  if( !zAncSql || !zSideSql ) return SQLITE_OK;
  rc = parseColumns(zAncSql, &aAnc, &nAnc);
  if( rc!=SQLITE_OK ) return rc;
  rc = parseColumns(zSideSql, &aSide, &nSide);
  if( rc!=SQLITE_OK ){
    freeColumns(aAnc, nAnc);
    return rc;
  }
  if( nSide>=nAnc ){
    *pbPrefix = 1;
    for(i=0; i<nAnc; i++){
      if( sqlite3_stricmp(aAnc[i].zName, aSide[i].zName)!=0
       || !parsedColumnDefinitionsMatch(&aAnc[i], &aSide[i]) ){
        *pbPrefix = 0;
        break;
      }
    }
  }
  *pnAnc = nAnc;
  *pnSide = nSide;
  for(i=0; pnAncRecord && i<nAnc; i++){
    if( !parsedColumnIsVirtual(&aAnc[i]) ) (*pnAncRecord)++;
  }
  freeColumns(aAnc, nAnc);
  freeColumns(aSide, nSide);
  return SQLITE_OK;
}

static int mergePass1CollectIndexes(
  MergePass1Ctx *c,
  const char *zName,
  MergeIndexInfo **paIdxInfo,
  int *pnIdxInfo
){
  Table *pTab;
  Index *pIdx;
  int nIdx = 0;
  MergeIndexInfo *aIdxInfo = 0;
  int nIdxInfo = 0;
  int rc = SQLITE_OK;

  *paIdxInfo = 0;
  *pnIdxInfo = 0;
  if( !zName || !c->db ) return SQLITE_OK;

  pTab = sqlite3FindTable(c->db, zName, "main");
  if( !pTab ) return SQLITE_OK;

  for(pIdx=pTab->pIndex; pIdx; pIdx=pIdx->pNext) nIdx++;
  if( nIdx<=0 ) return SQLITE_OK;

  aIdxInfo = sqlite3_malloc(nIdx * (int)sizeof(MergeIndexInfo));
  if( !aIdxInfo ){
    /* Else table rows merge with stale secondary indexes. */
    return SQLITE_NOMEM;
  }
  memset(aIdxInfo, 0, nIdx*(int)sizeof(MergeIndexInfo));

  for(pIdx=pTab->pIndex; pIdx; pIdx=pIdx->pNext){
    struct TableEntry *oursIdx;
    /* WITHOUT ROWID PK is the table tree; skip it. */
    if( pIdx->idxType==SQLITE_IDXTYPE_PRIMARYKEY && !HasRowid(pTab) ) continue;
    oursIdx = doltliteFindTableByNumber(c->aOurs, c->nOurs, pIdx->tnum);
    if( oursIdx ){
      MergeIndexInfo *mi = &aIdxInfo[nIdxInfo];
      mi->iTable = pIdx->tnum;
      memcpy(&mi->oursRoot, &oursIdx->root, sizeof(ProllyHash));
      mi->nColumn = pIdx->nKeyCol;
      mi->aiColumn = pIdx->aiColumn;
      mi->pKeyInfo = doltliteKeyInfoOfIndex(c->db, pIdx);
      if( !mi->pKeyInfo ){
        mergePass1FreeIdxInfo(aIdxInfo, nIdxInfo);
        return SQLITE_NOMEM;
      }
      mi->iPKey = pTab->iPKey;
      mi->pIdx = pIdx;
      nIdxInfo++;
    }
  }

  *paIdxInfo = aIdxInfo;
  *pnIdxInfo = nIdxInfo;
  return rc;
}

static int mergePass1RecordIndexPatches(
  MergePass1Ctx *c,
  MergeIndexInfo *aIdxInfo,
  int nIdxInfo
){
  int ix;
  for(ix=0; ix<nIdxInfo; ix++){
    if( c->nPatches >= c->nPatchesAlloc ){
      int newAlloc = c->nPatchesAlloc ? c->nPatchesAlloc*2 : 4;
      void *pNew = sqlite3_realloc(c->aPatches,
          newAlloc * (int)sizeof(IndexMergePatch));
      if( !pNew ) return SQLITE_NOMEM;
      c->aPatches = pNew;
      c->nPatchesAlloc = newAlloc;
    }
    c->aPatches[c->nPatches].iTable = aIdxInfo[ix].iTable;
    memcpy(&c->aPatches[c->nPatches].mergedRoot,
           &aIdxInfo[ix].mergedRoot, sizeof(ProllyHash));
    c->nPatches++;
  }
  return SQLITE_OK;
}

static int mergePass1MergeTableData(
  MergePass1Ctx *c,
  const char *zName,
  const char *zLogicalName,
  struct TableEntry *pOurs,
  struct TableEntry *pAnc,
  const ProllyHash *pTheirsRoot,
  int ourSchemaChanged,
  int theirSchemaChanged,
  int schemaChoice,
  struct TableEntry *pTheirsEntry
){
  ProllyHash mergedTableRoot;
  int nConflicts = 0;
  DoltliteConflictRow *aConflictRows = 0;
  MergeIndexInfo *aIdxInfo = 0;
  int nIdxInfo = 0;
  MergeRowPolicy rowPolicy;
  const MergeRowPolicy *pRowPolicy = 0;
  int rc;
  int handled = 0;

  memset(&rowPolicy, 0, sizeof(rowPolicy));

  if( zName && (ourSchemaChanged || theirSchemaChanged) ){
    SchemaEntry *pAncSe = findSchemaEntry(c->aAncSchema, c->nAncSchema, zName);
    SchemaEntry *pOurSe = findSchemaEntry(c->aOursSchema, c->nOursSchema, zName);
    SchemaEntry *pTheirSe = findSchemaEntry(
        c->aTheirsSchema, c->nTheirsSchema, zName);
    int bOurPrefix = 0, bTheirPrefix = 0;
    int nAncOur = 0, nAncTheir = 0;
    int nOur = 0, nTheir = 0;
    int nAncOurRecord = 0, nAncTheirRecord = 0;
    if( pAncSe && pOurSe && pTheirSe ){
      rc = mergePass1SchemaPrefixInfo(
          pAncSe->zSql, pOurSe->zSql, &bOurPrefix,
          &nAncOur, &nOur, &nAncOurRecord);
      if( rc==SQLITE_OK ){
        rc = mergePass1SchemaPrefixInfo(
            pAncSe->zSql, pTheirSe->zSql,
            &bTheirPrefix, &nAncTheir, &nTheir, &nAncTheirRecord);
      }
      if( rc!=SQLITE_OK ) return rc;
      if( bOurPrefix && bTheirPrefix && nAncOur==nAncTheir
       && nAncOurRecord==nAncTheirRecord
       && (nOur>nAncOur || nTheir>nAncTheir) ){
        rowPolicy.nDeleteCompareFields = nAncOurRecord;
        pRowPolicy = &rowPolicy;
      }
    }
  }

  rc = mergePass1CollectIndexes(c, zName, &aIdxInfo, &nIdxInfo);
  if( rc!=SQLITE_OK ) return rc;

  if( canFastMerge(c->db, zName, !ourSchemaChanged && !theirSchemaChanged) ){
    rc = prollyThreeWayMergeFast(
      doltliteGetChunkStore(c->db), doltliteGetCache(c->db),
      &pAnc->root, &pOurs->root, pTheirsRoot,
      pOurs->flags, &mergedTableRoot, &handled);
    if( rc!=SQLITE_OK ){
      mergePass1FreeIdxInfo(aIdxInfo, nIdxInfo);
      return rc;
    }
  }

  if( !handled ){
    rc = mergeTableRows(c->db, &pAnc->root, &pOurs->root,
                        pTheirsRoot, pOurs->flags,
                        pAnc->flags, pTheirsEntry->flags,
                        &mergedTableRoot, &nConflicts, &aConflictRows,
                        aIdxInfo, nIdxInfo, pRowPolicy);
    if( rc!=SQLITE_OK ){
      mergePass1FreeIdxInfo(aIdxInfo, nIdxInfo);
      return rc;
    }
  }

  rc = mergePass1RecordIndexPatches(c, aIdxInfo, nIdxInfo);
  mergePass1FreeIdxInfo(aIdxInfo, nIdxInfo);
  if( rc!=SQLITE_OK ) return rc;

  {
    struct TableEntry merged = *pOurs;
    memcpy(&merged.root, &mergedTableRoot, sizeof(ProllyHash));
    if( schemaChoice==SCHEMA_MERGE_THEIRS
     || (theirSchemaChanged && !ourSchemaChanged) ){
      memcpy(&merged.schemaHash, &pTheirsEntry->schemaHash, sizeof(ProllyHash));
      merged.flags = pTheirsEntry->flags;
    }
    c->aMerged[(*c->pnMerged)++] = merged;
  }

  if( nConflicts>0 ){
    *c->pTotalConflicts += nConflicts;
    rc = appendConflictTable(c->ppConflictTables, c->pnConflictTables,
                             zLogicalName ? zLogicalName : "",
                             nConflicts, aConflictRows);
    if( rc!=SQLITE_OK ) return rc;
  }
  return SQLITE_OK;
}

static int mergePass1ResolveOursEntry(
  MergePass1Ctx *c,
  int iOurs,
  const char **pzName,
  const char **pzLogicalName,
  const char **pzSchemaMergeName,
  const char **pzSchemaConflictTable,
  struct TableEntry **ppAnc,
  struct TableEntry **ppTheirs,
  int *pbSkipMaster
){
  const char *zName = c->aOurs[iOurs].zName;

  *pzName = zName;
  *pzLogicalName = zName;
  *pzSchemaMergeName = zName;
  *pzSchemaConflictTable = zName;
  *ppAnc = 0;
  *ppTheirs = 0;
  *pbSkipMaster = 0;

  if( c->aOurs[iOurs].iTable==1 ){
    *pbSkipMaster = 1;
    return SQLITE_OK;
  }

  if( !zName ){
    SchemaEntry *pOurSe = findSchemaEntryByRootpage(
        c->aOursSchema, c->nOursSchema, c->aOurs[iOurs].iTable);
    if( pOurSe && pOurSe->zName && pOurSe->zType
     && strcmp(pOurSe->zType, "index")==0 ){
      *pzLogicalName = pOurSe->zName;
      *pzSchemaMergeName = pOurSe->zName;
      *pzSchemaConflictTable = pOurSe->zTblName
          ? pOurSe->zTblName : pOurSe->zName;
      *ppAnc = findCatalogEntryBySchemaObject(
          c->aAnc, c->nAnc, c->aAncSchema, c->nAncSchema,
          pOurSe->zType, pOurSe->zName, pOurSe->zTblName);
      *ppTheirs = findCatalogEntryBySchemaObject(
          c->aTheirs, c->nTheirs, c->aTheirsSchema, c->nTheirsSchema,
          pOurSe->zType, pOurSe->zName, pOurSe->zTblName);
      return SQLITE_OK;
    }
    *ppAnc = doltliteFindTableByNumber(c->aAnc, c->nAnc, c->aOurs[iOurs].iTable);
    *ppTheirs = doltliteFindTableByNumber(
        c->aTheirs, c->nTheirs, c->aOurs[iOurs].iTable);
    return SQLITE_OK;
  }

  *ppAnc = doltliteFindTableByName(c->aAnc, c->nAnc, zName);
  *ppTheirs = doltliteFindTableByName(c->aTheirs, c->nTheirs, zName);
  if( !*ppAnc ){
    struct TableEntry *pByNo = doltliteFindTableByNumber(
        c->aAnc, c->nAnc, c->aOurs[iOurs].iTable);
    if( pByNo && pByNo->zName && strcmp(pByNo->zName, zName)!=0
     && !doltliteFindTableByName(c->aOurs, c->nOurs, pByNo->zName) ){
      struct TableEntry *pTheirsByNo;
      /* Drop plus a dual add: the new name is on both sides and was not
      ** in the ancestor. Reusing the dropped table's number is not a rename. */
      if( doltliteFindTableByName(c->aTheirs, c->nTheirs, zName)
       && !doltliteFindTableByName(c->aAnc, c->nAnc, zName) ){
        return SQLITE_OK;
      }
      pTheirsByNo = doltliteFindTableByNumber(
          c->aTheirs, c->nTheirs, c->aOurs[iOurs].iTable);
      if( pTheirsByNo && !pTheirsByNo->zName ){
        pTheirsByNo = 0;
        pByNo = 0;
      }else if( pTheirsByNo
             && strcmp(pTheirsByNo->zName, pByNo->zName)!=0
             && strcmp(pTheirsByNo->zName, zName)!=0 ){
        pTheirsByNo = 0;
        pByNo = 0;
      }
      if( pByNo ){
        *ppAnc = pByNo;
        if( !*ppTheirs && pTheirsByNo ) *ppTheirs = pTheirsByNo;
      }
    }
  }
  return SQLITE_OK;
}

static int mergePass1AddedSchemaMatches(
  MergePass1Ctx *c,
  const char *zObjectName,
  int iOurs,
  struct TableEntry *theirsEntry
){
  SchemaEntry *ourSE;
  SchemaEntry *theirSE;
  if( prollyHashCompare(&c->aOurs[iOurs].schemaHash,
                        &theirsEntry->schemaHash)==0 ){
    return 1;
  }
  if( !zObjectName ) return 0;
  ourSE = findSchemaEntry(c->aOursSchema, c->nOursSchema, zObjectName);
  theirSE = findSchemaEntry(c->aTheirsSchema, c->nTheirsSchema, zObjectName);
  if( !ourSE || !theirSE || !ourSE->zSql || !theirSE->zSql ) return 0;
  return strcmp(ourSE->zSql, theirSE->zSql)==0;
}

static int mergePass1OursAdded(
  MergePass1Ctx *c,
  int iOurs,
  const char *zName,
  const char *zSchemaMergeName,
  const char *zSchemaConflictTable,
  struct TableEntry *theirsEntry
){
  int rc;

  /* Index over a column they dropped cannot load. Dolt drops it too. */
  if( !zName && zSchemaMergeName && zSchemaConflictTable ){
    SchemaEntry *pOurIdx = findSchemaEntry(
        c->aOursSchema, c->nOursSchema, zSchemaMergeName);
    SchemaEntry *pAncTbl = findSchemaEntry(
        c->aAncSchema, c->nAncSchema, zSchemaConflictTable);
    SchemaEntry *pTheirTbl = findSchemaEntry(
        c->aTheirsSchema, c->nTheirsSchema, zSchemaConflictTable);
    char *zGone = 0;
    if( pOurIdx && pAncTbl && pTheirTbl
     && mergeIndexColumnGoneFrom(pOurIdx->zSql, pAncTbl->zSql,
                                 pTheirTbl->zSql, &zGone) ){
      sqlite3_free(zGone);
      return SQLITE_OK;
    }
    sqlite3_free(zGone);
  }

  if( theirsEntry ){
    if( !zName && c->bDisjointSchemaChanges ){
      c->aMerged[(*c->pnMerged)++] = c->aOurs[iOurs];
      return SQLITE_OK;
    }
    if( zName
     && (strcmp(zName, "sqlite_stat1")==0
      || strcmp(zName, "sqlite_stat4")==0) ){
      c->aMerged[(*c->pnMerged)++] = c->aOurs[iOurs];
      return SQLITE_OK;
    }
    if( mergePass1AddedSchemaMatches(
          c, zName ? zName : zSchemaMergeName, iOurs, theirsEntry) ){
      if( prollyHashCompare(&c->aOurs[iOurs].root, &theirsEntry->root)==0 ){
        c->aMerged[(*c->pnMerged)++] = c->aOurs[iOurs];
        return SQLITE_OK;
      }
      if( !zName ){
        if( zSchemaMergeName && zSchemaMergeName[0] ){
          rc = mergeAppendReindexName(
              c->pazReindex, c->pnReindex, zSchemaMergeName);
          if( rc!=SQLITE_OK ) return rc;
        }
        c->aMerged[(*c->pnMerged)++] = c->aOurs[iOurs];
        return SQLITE_OK;
      }
      if( ((c->aOurs[iOurs].flags ^ theirsEntry->flags)
           & PROLLY_NODE_INTKEY)!=0 ){
        if( c->pzErrMsg ){
          sqlite3_free(*c->pzErrMsg);
          *c->pzErrMsg = sqlite3_mprintf(
              "cannot merge because table '%s' has different primary keys",
              zName);
        }
        return SQLITE_ERROR;
      }
      {
        struct TableEntry ancEmpty;
        memset(&ancEmpty, 0, sizeof(ancEmpty));
        ancEmpty.flags = c->aOurs[iOurs].flags;
        return mergePass1MergeTableData(
            c, zName, zName, &c->aOurs[iOurs], &ancEmpty,
            &theirsEntry->root, 0, 0, SCHEMA_MERGE_DEFAULT, theirsEntry);
      }
    }
    rc = mergePass1NoteSchemaConflict(c, zSchemaConflictTable, zSchemaMergeName);
    if( rc!=SQLITE_OK ) return rc;
  }
  if( !theirsEntry && !zName && zSchemaMergeName && zSchemaMergeName[0]
   && zSchemaConflictTable && zSchemaConflictTable[0] ){
    struct TableEntry *pAncTable = doltliteFindTableByName(
        c->aAnc, c->nAnc, zSchemaConflictTable);
    struct TableEntry *pTheirTable = doltliteFindTableByName(
        c->aTheirs, c->nTheirs, zSchemaConflictTable);
    if( pTheirTable && (!pAncTable
     || prollyHashCompare(&pTheirTable->root, &pAncTable->root)!=0) ){
      rc = mergeAppendReindexName(
          c->pazReindex, c->pnReindex, zSchemaMergeName);
      if( rc!=SQLITE_OK ) return rc;
    }
  }
  c->aMerged[(*c->pnMerged)++] = c->aOurs[iOurs];
  return SQLITE_OK;
}

static int mergePass1OursModifyTheirsDelete(
  MergePass1Ctx *c,
  int iOurs,
  const char *zName,
  const char *zSchemaMergeName,
  const char *zSchemaConflictTable,
  struct TableEntry *ancEntry
){
  int oursChanged = prollyHashCompare(&c->aOurs[iOurs].root, &ancEntry->root)!=0
                 || prollyHashCompare(&c->aOurs[iOurs].schemaHash,
                                      &ancEntry->schemaHash)!=0;
  int rc;

  if( zName && mergeTableRenameOtherDrop(
        c->aAnc, c->nAnc, c->aTheirs, c->nTheirs, c->aOurs, c->nOurs,
        c->aAncSchema, c->nAncSchema, c->aOursSchema, c->nOursSchema,
        &c->aOurs[iOurs], 0) ){
    c->aMerged[(*c->pnMerged)++] = c->aOurs[iOurs];
    return SQLITE_OK;
  }

  if( !oursChanged ) return SQLITE_OK;

  /* Index root moves with table data; only a definition change conflicts.
  ** Unchanged definition: DROP wins. */
  if( !zName && zSchemaMergeName && zSchemaMergeName[0]
   && !schemaEntryChangedByName(c->aAncSchema, c->nAncSchema,
                                c->aOursSchema, c->nOursSchema,
                                zSchemaMergeName) ){
    return SQLITE_OK;
  }
  if( !zName && zSchemaMergeName && zSchemaMergeName[0] ){
    if( c->ppSchemaActions && c->pnSchemaActions ){
      rc = recordSchemaAddColumns(c->ppSchemaActions, c->pnSchemaActions,
                                  zSchemaMergeName, 0, 0);
      if( rc!=SQLITE_OK ) return rc;
    }
    c->aMerged[(*c->pnMerged)++] = c->aOurs[iOurs];
    return SQLITE_OK;
  }
  rc = mergePass1NoteSchemaConflict(c, zSchemaConflictTable, zSchemaMergeName);
  if( rc!=SQLITE_OK ) return rc;
  c->aMerged[(*c->pnMerged)++] = c->aOurs[iOurs];
  return SQLITE_OK;
}

/* PK signature: key columns in order, types, collations, sort dirs.
** No declared PK yields empty, matching SQLite rowid-keyed tables. */
static int mergePass1AppendSigRow(
  char **pzSig,
  const char *zName,
  const char *zType,
  const char *zColl,
  int bDesc
){
  char *zNew = sqlite3_mprintf("%s%s%s %s %s %s", *pzSig ? *pzSig : "",
                               *pzSig ? "," : "",
                               zName ? zName : "",
                               zType ? zType : "",
                               zColl ? zColl : "BINARY",
                               bDesc ? "DESC" : "ASC");
  sqlite3_free(*pzSig);
  *pzSig = zNew;
  return zNew ? SQLITE_OK : SQLITE_NOMEM;
}

static int mergePass1PkSignature(
  const char *zSql,
  const char *zTableName,
  char **pzSig
){
  sqlite3 *tmp = 0;
  sqlite3_stmt *pStmt = 0;
  char *zQuery = 0;
  char *zSig = 0;
  int rc;

  *pzSig = 0;
  rc = sqlite3_open(":memory:", &tmp);
  if( rc!=SQLITE_OK ) goto done;
  rc = sqlite3_exec(tmp, zSql, 0, 0, 0);
  if( rc!=SQLITE_OK ) goto done;

  zQuery = sqlite3_mprintf(
      "SELECT x.name, i.type, x.coll, x.desc "
      "FROM pragma_index_list(%Q) AS l "
      "JOIN pragma_index_xinfo(l.name) AS x "
      "LEFT JOIN pragma_table_info(%Q) AS i ON i.name = x.name "
      "WHERE l.origin='pk' AND x.key=1 ORDER BY x.seqno",
      zTableName, zTableName);
  if( !zQuery ){ rc = SQLITE_NOMEM; goto done; }
  rc = sqlite3_prepare_v2(tmp, zQuery, -1, &pStmt, 0);
  if( rc!=SQLITE_OK ) goto done;
  while( (rc = sqlite3_step(pStmt))==SQLITE_ROW ){
    rc = mergePass1AppendSigRow(&zSig,
             (const char*)sqlite3_column_text(pStmt, 0),
             (const char*)sqlite3_column_text(pStmt, 1),
             (const char*)sqlite3_column_text(pStmt, 2),
             sqlite3_column_int(pStmt, 3));
    if( rc!=SQLITE_OK ) goto done;
  }
  if( rc!=SQLITE_DONE ) goto done;
  sqlite3_finalize(pStmt);
  pStmt = 0;
  sqlite3_free(zQuery);
  zQuery = 0;

  if( !zSig ){
    zQuery = sqlite3_mprintf(
        "SELECT name, type FROM pragma_table_info(%Q) WHERE pk>0 ORDER BY pk",
        zTableName);
    if( !zQuery ){ rc = SQLITE_NOMEM; goto done; }
    rc = sqlite3_prepare_v2(tmp, zQuery, -1, &pStmt, 0);
    if( rc!=SQLITE_OK ) goto done;
    while( (rc = sqlite3_step(pStmt))==SQLITE_ROW ){
      rc = mergePass1AppendSigRow(&zSig,
               (const char*)sqlite3_column_text(pStmt, 0),
               (const char*)sqlite3_column_text(pStmt, 1),
               0, 0);
      if( rc!=SQLITE_OK ) goto done;
    }
  }
  rc = rc==SQLITE_DONE ? SQLITE_OK : rc;

done:
  if( pStmt ) sqlite3_finalize(pStmt);
  sqlite3_free(zQuery);
  if( tmp ) sqlite3_close(tmp);
  if( rc!=SQLITE_OK ){
    sqlite3_free(zSig);
    return rc;
  }
  *pzSig = zSig ? zSig : sqlite3_mprintf("");
  return *pzSig ? SQLITE_OK : SQLITE_NOMEM;
}

/* Different PKs are different keyspaces; refuse, as Dolt does. */
static int mergePass1CheckPrimaryKeysMatch(
  MergePass1Ctx *c,
  const char *zName,
  struct TableEntry *pOurs,
  struct TableEntry *pAnc,
  struct TableEntry *pTheirs
){
  SchemaEntry *ancSE = findSchemaEntry(c->aAncSchema, c->nAncSchema, zName);
  SchemaEntry *ourSE = findSchemaEntry(c->aOursSchema, c->nOursSchema, zName);
  SchemaEntry *theirSE = findSchemaEntry(
      c->aTheirsSchema, c->nTheirsSchema, zName);
  char *zAncSig = 0, *zOursSig = 0, *zTheirsSig = 0;
  int vsTheirs = 0, vsAncestor = 0;
  int rc = SQLITE_OK;

  if( !ancSE || !ancSE->zSql || !ourSE || !ourSE->zSql
   || !theirSE || !theirSE->zSql ){
    return SQLITE_OK;
  }

  rc = mergePass1PkSignature(ancSE->zSql, zName, &zAncSig);
  if( rc==SQLITE_OK ) rc = mergePass1PkSignature(ourSE->zSql, zName, &zOursSig);
  if( rc==SQLITE_OK ){
    rc = mergePass1PkSignature(theirSE->zSql, zName, &zTheirsSig);
  }
  if( rc==SQLITE_OK ){
    vsTheirs = sqlite3_stricmp(zOursSig, zTheirsSig)!=0
            || ((pOurs->flags ^ pTheirs->flags) & PROLLY_NODE_INTKEY)!=0;
    vsAncestor = sqlite3_stricmp(zOursSig, zAncSig)!=0
              || ((pOurs->flags ^ pAnc->flags) & PROLLY_NODE_INTKEY)!=0;
  }
  sqlite3_free(zAncSig);
  sqlite3_free(zOursSig);
  sqlite3_free(zTheirsSig);
  if( rc!=SQLITE_OK ) return rc;
  if( !vsTheirs && !vsAncestor ) return SQLITE_OK;
  if( c->pzErrMsg ){
    sqlite3_free(*c->pzErrMsg);
    *c->pzErrMsg = sqlite3_mprintf(
        "cannot merge because table '%s' has different primary keys%s",
        zName, vsTheirs ? "" : " in its common ancestor");
  }
  return SQLITE_ERROR;
}

static int mergePass1SchemaAppendsColumns(
  const char *zAncSql,
  const char *zSideSql,
  int *pbAppends
);

/* Cell merge is by merged column position. Relayout the unmerged side
** first or dropped columns shift later values and the ancestor looks
** changed. zOtherSql is that side's layout, not always the schema array
** (adopting theirs overwrites our SQL). */
static int mergePass1RelayoutToMergedSchema(
  MergePass1Ctx *c,
  const char *zName,
  const char *zAncSql,
  const char *zMergedSql,
  const char *zOtherSql,
  u8 flags,
  const ProllyHash *pMergedRoot,
  const ProllyHash *pOtherRoot,
  const ProllyHash *pAncRoot,
  ProllyHash *pOtherOut,
  ProllyHash *pAncOut,
  int *pbRelaid
){
  int bFillSharedDefaults = 0;
  int rc;

  *pbRelaid = 0;
  if( !zAncSql || !zMergedSql || !zOtherSql ) return SQLITE_OK;

  rc = mergePass1SchemaAppendsColumns(
      zAncSql, zMergedSql, &bFillSharedDefaults);
  if( rc!=SQLITE_OK ) return rc;

  rc = normalizeSideToMergedLayout(c->db, zName, pMergedRoot, pOtherRoot,
                                   flags, zAncSql,
                                   zMergedSql, zOtherSql,
                                   bFillSharedDefaults, pOtherOut);
  if( rc!=SQLITE_OK ) return rc;
  rc = normalizeSideToMergedLayout(c->db, zName, pMergedRoot, pAncRoot,
                                   flags, zAncSql,
                                   zMergedSql, zAncSql,
                                   bFillSharedDefaults, pAncOut);
  if( rc!=SQLITE_OK ) return rc;
  *pbRelaid = 1;
  return SQLITE_OK;
}

static int mergePass1SchemaAppendsColumns(
  const char *zAncSql,
  const char *zSideSql,
  int *pbAppends
){
  int bPrefix = 0;
  int nAnc = 0, nSide = 0;
  int rc;

  *pbAppends = 0;
  rc = mergePass1SchemaPrefixInfo(
      zAncSql, zSideSql, &bPrefix, &nAnc, &nSide, 0);
  if( rc==SQLITE_OK ) *pbAppends = bPrefix && nSide>nAnc;
  return rc;
}

/* One side changed columns: that layout wins; move the other and ancestor. */
static int mergePass1RelayoutOneSidedSchema(
  MergePass1Ctx *c,
  const char *zName,
  int bMergedIsOurs,
  struct TableEntry *pOurs,
  struct TableEntry *pAnc,
  struct TableEntry *pTheirs,
  ProllyHash *pOtherOut,
  ProllyHash *pAncOut,
  int *pbRelaid
){
  SchemaEntry *ourSE = findSchemaEntry(c->aOursSchema, c->nOursSchema, zName);
  SchemaEntry *theirSE = findSchemaEntry(c->aTheirsSchema, c->nTheirsSchema, zName);
  SchemaEntry *ancSE = findSchemaEntry(c->aAncSchema, c->nAncSchema, zName);

  *pbRelaid = 0;
  if( !ancSE || !ourSE || !theirSE ) return SQLITE_OK;

  return mergePass1RelayoutToMergedSchema(c, zName, ancSE->zSql,
      bMergedIsOurs ? ourSE->zSql : theirSE->zSql,
      bMergedIsOurs ? theirSE->zSql : ourSE->zSql,
      pOurs->flags,
      bMergedIsOurs ? &pOurs->root : &pTheirs->root,
      bMergedIsOurs ? &pTheirs->root : &pOurs->root,
      &pAnc->root,
      pOtherOut, pAncOut, pbRelaid);
}

static int mergePass1BothSides(
  MergePass1Ctx *c,
  int iOurs,
  const char *zName,
  const char *zLogicalName,
  const char *zSchemaMergeName,
  const char *zSchemaConflictTable,
  struct TableEntry *ancEntry,
  struct TableEntry *theirsEntry
){
  int oursChanged = prollyHashCompare(&c->aOurs[iOurs].root, &ancEntry->root)!=0
                 || prollyHashCompare(&c->aOurs[iOurs].schemaHash,
                                      &ancEntry->schemaHash)!=0;
  int theirsChanged = prollyHashCompare(&theirsEntry->root, &ancEntry->root)!=0;
  int ourSchemaChanged = prollyHashCompare(
      &c->aOurs[iOurs].schemaHash, &ancEntry->schemaHash)!=0;
  int theirSchemaChanged = prollyHashCompare(
      &theirsEntry->schemaHash, &ancEntry->schemaHash)!=0;
  int bNamedSchemaObject = (!zName && zSchemaMergeName && zSchemaMergeName[0]);
  int skipRowMerge = 0;
  int schemaChoice = SCHEMA_MERGE_DEFAULT;
  int bDualAddColMerge = 0;
  int bSchemaConflict = 0;
  ProllyHash theirsNormRoot;
  ProllyHash otherNormRoot;
  ProllyHash ancNormRoot;
  char *zOursPrevSql = 0;
  struct TableEntry oursAdj;
  struct TableEntry ancAdj;
  struct TableEntry *pMergeOurs = &c->aOurs[iOurs];
  struct TableEntry *pMergeAnc = ancEntry;
  const ProllyHash *pMergeTheirsRoot = &theirsEntry->root;
  int rc = SQLITE_OK;

  if( zSchemaMergeName && zSchemaMergeName[0]
   && !(ancEntry && ancEntry->zName && zName
        && strcmp(ancEntry->zName, zName)!=0) ){
    ourSchemaChanged = ourSchemaChanged || schemaEntryChangedByName(
        c->aAncSchema, c->nAncSchema, c->aOursSchema, c->nOursSchema,
        zSchemaMergeName);
    theirSchemaChanged = theirSchemaChanged || schemaEntryChangedByName(
        c->aAncSchema, c->nAncSchema, c->aTheirsSchema, c->nTheirsSchema,
        zSchemaMergeName);
  }

  /* Untouched theirs keeps ours verbatim; PKs need not agree. */
  if( zName && (ourSchemaChanged || theirSchemaChanged)
   && (theirsChanged || theirSchemaChanged) ){
    rc = mergePass1CheckPrimaryKeysMatch(
        c, zName, &c->aOurs[iOurs], ancEntry, theirsEntry);
    if( rc!=SQLITE_OK ) return rc;
  }

  if( ourSchemaChanged && theirSchemaChanged
   && (bNamedSchemaObject
       || prollyHashCompare(&c->aOurs[iOurs].schemaHash,
                            &theirsEntry->schemaHash)!=0) ){
    rc = tryResolveSchemaDivergence(
      c->db, zSchemaMergeName, c->pCatAnc, c->pCatOurs, c->pCatTheirs,
      c->ppSchemaActions, c->pnSchemaActions, &skipRowMerge,
      &schemaChoice, c->pzErrMsg);
    if( rc==SQLITE_ERROR ){
      sqlite3_free(c->pzErrMsg ? *c->pzErrMsg : 0);
      if( c->pzErrMsg ) *c->pzErrMsg = 0;
      rc = mergePass1NoteSchemaConflict(c, zSchemaConflictTable, zSchemaMergeName);
      if( rc!=SQLITE_OK ) return rc;
      c->aMerged[(*c->pnMerged)++] = c->aOurs[iOurs];
      skipRowMerge = 1;
      bSchemaConflict = 1;
    }else if( rc!=SQLITE_OK ){
      return rc;
    }
    if( !bSchemaConflict && schemaChoice==SCHEMA_MERGE_THEIRS ){
      SchemaEntry *pOurSe;
      SchemaEntry *pTheirSe;
      char *zSql;
      pOurSe = findSchemaEntry(
          c->aOursSchema, c->nOursSchema, zSchemaMergeName);
      pTheirSe = findSchemaEntry(
          c->aTheirsSchema, c->nTheirsSchema, zSchemaMergeName);
      if( !pOurSe && zName ){
        pOurSe = findSchemaEntry(c->aOursSchema, c->nOursSchema, zName);
      }
      if( !pTheirSe && ancEntry && ancEntry->zName ){
        pTheirSe = findSchemaEntry(
            c->aTheirsSchema, c->nTheirsSchema, ancEntry->zName);
      }
      if( !pTheirSe ){
        pTheirSe = findSchemaEntryByRootpage(
            c->aTheirsSchema, c->nTheirsSchema, c->aOurs[iOurs].iTable);
      }
      zSql = pTheirSe && pTheirSe->zSql
                 ? sqlite3_mprintf("%s", pTheirSe->zSql) : 0;
      if( !pOurSe || !zSql ){
        sqlite3_free(zSql);
        return pOurSe ? SQLITE_NOMEM : SQLITE_CORRUPT;
      }
      /* Ours still uses the old layout; keep it for the relayout below. */
      zOursPrevSql = pOurSe->zSql;
      pOurSe->zSql = zSql;
    }
    if( !bSchemaConflict && skipRowMerge && zName ){
      SchemaEntry *ourSE = findSchemaEntry(c->aOursSchema, c->nOursSchema, zName);
      SchemaEntry *theirSE = findSchemaEntry(
          c->aTheirsSchema, c->nTheirsSchema, zName);
      SchemaEntry *ancSE = findSchemaEntry(c->aAncSchema, c->nAncSchema, zName);
      if( ancSE && ancSE->zSql && ourSE && ourSE->zSql
       && theirSE && theirSE->zSql ){
        int bRelaid = 0;
        rc = mergePass1RelayoutToMergedSchema(c, zName,
            ancSE->zSql, ourSE->zSql, theirSE->zSql,
            c->aOurs[iOurs].flags, &c->aOurs[iOurs].root,
            &theirsEntry->root, &ancEntry->root,
            &theirsNormRoot, &ancNormRoot, &bRelaid);
        if( rc!=SQLITE_OK ) return rc;
        ancAdj = *ancEntry;
        memcpy(&ancAdj.root, &ancNormRoot, sizeof(ProllyHash));
        pMergeAnc = &ancAdj;
        pMergeTheirsRoot = &theirsNormRoot;
        bDualAddColMerge = 1;
        skipRowMerge = 0;
      }else{
        c->aMerged[(*c->pnMerged)++] = c->aOurs[iOurs];
      }
    }else if( !bSchemaConflict && skipRowMerge ){
      c->aMerged[(*c->pnMerged)++] = c->aOurs[iOurs];
    }
  }

  /* sqlite_sequence / sqlite_stat* are derived; skip row merge. */
  if( !skipRowMerge && zName
   && strcmp(zName, "sqlite_sequence")==0
   && oursChanged && theirsChanged ){
    c->aMerged[(*c->pnMerged)++] = c->aOurs[iOurs];
    skipRowMerge = 1;
  }
  if( !skipRowMerge && zName
   && oursChanged && theirsChanged
   && (strcmp(zName, "sqlite_stat1")==0
    || strcmp(zName, "sqlite_stat4")==0) ){
    c->aMerged[(*c->pnMerged)++] = c->aOurs[iOurs];
    skipRowMerge = 1;
  }

  if( skipRowMerge ){
    sqlite3_free(zOursPrevSql);
    return SQLITE_OK;
  }

  /* Adopted their schema for a rename: our rows are off-layout. Judge
  ** the move on the schema, not on whether either side wrote rows. */
  if( zName && zOursPrevSql ){
    SchemaEntry *ancSE = findSchemaEntry(c->aAncSchema, c->nAncSchema, zName);
    SchemaEntry *mergedSE = findSchemaEntry(c->aOursSchema, c->nOursSchema, zName);
    int bRelaid = 0;
    if( ancSE && mergedSE ){
      rc = mergePass1RelayoutToMergedSchema(c, zName, ancSE->zSql,
          mergedSE->zSql, zOursPrevSql, c->aOurs[iOurs].flags,
          &theirsEntry->root, &c->aOurs[iOurs].root, &ancEntry->root,
          &otherNormRoot, &ancNormRoot, &bRelaid);
      if( rc!=SQLITE_OK ){
        sqlite3_free(zOursPrevSql);
        return rc;
      }
    }
    if( bRelaid ){
      ancAdj = *ancEntry;
      memcpy(&ancAdj.root, &ancNormRoot, sizeof(ProllyHash));
      pMergeAnc = &ancAdj;
      oursAdj = c->aOurs[iOurs];
      memcpy(&oursAdj.root, &otherNormRoot, sizeof(ProllyHash));
      pMergeOurs = &oursAdj;
    }
  }
  sqlite3_free(zOursPrevSql);
  zOursPrevSql = 0;

  /* Mirror: we kept our schema, so theirs is the off-layout side. */
  if( zName && !bSchemaConflict && schemaChoice==SCHEMA_MERGE_OURS ){
    SchemaEntry *ancSE = findSchemaEntry(c->aAncSchema, c->nAncSchema, zName);
    SchemaEntry *ourSE = findSchemaEntry(c->aOursSchema, c->nOursSchema, zName);
    SchemaEntry *theirSE = findSchemaEntry(c->aTheirsSchema, c->nTheirsSchema, zName);
    int bRelaid = 0;
    if( ancSE && ourSE && theirSE ){
      rc = mergePass1RelayoutToMergedSchema(c, zName, ancSE->zSql,
          ourSE->zSql, theirSE->zSql, c->aOurs[iOurs].flags,
          &c->aOurs[iOurs].root, &theirsEntry->root, &ancEntry->root,
          &otherNormRoot, &ancNormRoot, &bRelaid);
      if( rc!=SQLITE_OK ) return rc;
    }
    if( bRelaid ){
      ancAdj = *ancEntry;
      memcpy(&ancAdj.root, &ancNormRoot, sizeof(ProllyHash));
      pMergeAnc = &ancAdj;
      pMergeTheirsRoot = &otherNormRoot;
    }
  }

  if( zName && oursChanged && theirsChanged
   && ourSchemaChanged!=theirSchemaChanged ){
    int bRelaid = 0;
    rc = mergePass1RelayoutOneSidedSchema(
        c, zName, ourSchemaChanged, &c->aOurs[iOurs], ancEntry, theirsEntry,
        &otherNormRoot, &ancNormRoot, &bRelaid);
    if( rc!=SQLITE_OK ) return rc;
    if( bRelaid ){
      ancAdj = *ancEntry;
      memcpy(&ancAdj.root, &ancNormRoot, sizeof(ProllyHash));
      pMergeAnc = &ancAdj;
      if( ourSchemaChanged ){
        pMergeTheirsRoot = &otherNormRoot;
      }else{
        oursAdj = c->aOurs[iOurs];
        memcpy(&oursAdj.root, &otherNormRoot, sizeof(ProllyHash));
        pMergeOurs = &oursAdj;
      }
    }
  }

  if( bDualAddColMerge || (oursChanged && theirsChanged) ){
    return mergePass1MergeTableData(
        c, zName, zLogicalName, pMergeOurs, pMergeAnc,
        pMergeTheirsRoot, ourSchemaChanged, theirSchemaChanged,
        schemaChoice, theirsEntry);
  }
  if( theirsChanged ){
    struct TableEntry merged = *pMergeOurs;
    memcpy(&merged.root, &theirsEntry->root, sizeof(ProllyHash));
    memcpy(&merged.schemaHash, &theirsEntry->schemaHash, sizeof(ProllyHash));
    merged.flags = theirsEntry->flags;
    c->aMerged[(*c->pnMerged)++] = merged;
  }else{
    c->aMerged[(*c->pnMerged)++] = *pMergeOurs;
  }
  return SQLITE_OK;
}

static int mergePass1MergeOursEntry(MergePass1Ctx *c, int iOurs){
  const char *zName = 0;
  const char *zLogicalName = 0;
  const char *zSchemaMergeName = 0;
  const char *zSchemaConflictTable = 0;
  struct TableEntry *ancEntry = 0;
  struct TableEntry *theirsEntry = 0;
  int bSkipMaster = 0;
  int rc;

  rc = mergePass1ResolveOursEntry(c, iOurs,
      &zName, &zLogicalName, &zSchemaMergeName, &zSchemaConflictTable,
      &ancEntry, &theirsEntry, &bSkipMaster);
  if( rc!=SQLITE_OK ) return rc;
  if( bSkipMaster ) return SQLITE_OK;

  if( hasSchemaConflictObject(*c->ppConflictTables, *c->pnConflictTables,
                              zSchemaMergeName)
   || (zName && hasSchemaConflictTable(*c->ppConflictTables,
                                       *c->pnConflictTables, zName)) ){
    c->aMerged[(*c->pnMerged)++] = c->aOurs[iOurs];
    return SQLITE_OK;
  }

  if( !ancEntry ){
    return mergePass1OursAdded(c, iOurs, zName, zSchemaMergeName,
                               zSchemaConflictTable, theirsEntry);
  }
  if( !theirsEntry ){
    return mergePass1OursModifyTheirsDelete(c, iOurs, zName,
        zSchemaMergeName, zSchemaConflictTable, ancEntry);
  }
  return mergePass1BothSides(c, iOurs, zName, zLogicalName,
      zSchemaMergeName, zSchemaConflictTable, ancEntry, theirsEntry);
}

static int mergePass1TheirsModifyDelete(MergePass1Ctx *c){
  int i, rc;

  for(i=0; i<c->nTheirs; i++){
    const char *zObject = c->aTheirs[i].zName;
    const char *zTable = zObject;
    struct TableEntry *pAncEntry = 0;
    struct TableEntry *pOurEntry = 0;
    int changed = 0;

    if( c->aTheirs[i].iTable<=1 ) continue;
    if( zObject ){
      pAncEntry = doltliteFindTableByName(c->aAnc, c->nAnc, zObject);
      pOurEntry = doltliteFindTableByName(c->aOurs, c->nOurs, zObject);
      if( !pOurEntry ){
        struct TableEntry *pByNo = doltliteFindTableByNumber(
            c->aOurs, c->nOurs, c->aTheirs[i].iTable);
        if( pByNo && pByNo->zName
         && doltliteFindTableByName(c->aTheirs, c->nTheirs, pByNo->zName)
         && doltliteFindTableByName(c->aOurs, c->nOurs, pByNo->zName)
         && !doltliteFindTableByName(c->aAnc, c->nAnc, pByNo->zName) ){
          pByNo = 0;
        }
        if( pByNo && pByNo->zName && pAncEntry && pAncEntry->zName
         && strcmp(pByNo->zName, pAncEntry->zName)!=0
         && strcmp(zObject, pAncEntry->zName)!=0 ){
          pByNo = 0;
        }
        pOurEntry = pByNo;
      }
      if( pAncEntry ){
        changed = prollyHashCompare(&c->aTheirs[i].root, &pAncEntry->root)!=0
               || prollyHashCompare(&c->aTheirs[i].schemaHash,
                                    &pAncEntry->schemaHash)!=0;
      }
    }else{
      SchemaEntry *pTheirSe = findSchemaEntryByRootpage(
          c->aTheirsSchema, c->nTheirsSchema, c->aTheirs[i].iTable);
      if( !pTheirSe || !pTheirSe->zName || !pTheirSe->zType
       || strcmp(pTheirSe->zType, "index")!=0 ){
        continue;
      }
      zObject = pTheirSe->zName;
      zTable = pTheirSe->zTblName ? pTheirSe->zTblName : pTheirSe->zName;
      pAncEntry = findCatalogEntryBySchemaObject(
          c->aAnc, c->nAnc, c->aAncSchema, c->nAncSchema,
          pTheirSe->zType, pTheirSe->zName, pTheirSe->zTblName);
      pOurEntry = findCatalogEntryBySchemaObject(
          c->aOurs, c->nOurs, c->aOursSchema, c->nOursSchema,
          pTheirSe->zType, pTheirSe->zName, pTheirSe->zTblName);
      if( pAncEntry ){
        changed = schemaEntryChangedByName(c->aAncSchema, c->nAncSchema,
                                           c->aTheirsSchema, c->nTheirsSchema,
                                           pTheirSe->zName);
      }
    }
    if( !pAncEntry || pOurEntry || !changed ) continue;
    if( !c->aTheirs[i].zName ){
      if( c->ppSchemaActions && c->pnSchemaActions ){
        rc = recordSchemaAddColumns(c->ppSchemaActions, c->pnSchemaActions,
                                    zObject, 0, 0);
        if( rc!=SQLITE_OK ) return rc;
      }
      continue;
    }
    rc = mergePass1NoteSchemaConflict(c, zTable, zObject);
    if( rc!=SQLITE_OK ) return rc;
  }
  return SQLITE_OK;
}

/* Ancestor names one side renamed and the other dropped. Dolt keeps
** the renamed table from either branch. */
static int mergePass1CollectRenameOverDrop(
  MergePass1Ctx *c,
  MergeRowPolicy *pPolicy
){
  int dir;
  for(dir=0; dir<2; dir++){
    struct TableEntry *aRenamed = dir ? c->aOurs : c->aTheirs;
    int nRenamed = dir ? c->nOurs : c->nTheirs;
    struct TableEntry *aDropped = dir ? c->aTheirs : c->aOurs;
    int nDropped = dir ? c->nTheirs : c->nOurs;
    SchemaEntry *aRenamedSchema = dir ? c->aOursSchema : c->aTheirsSchema;
    int nRenamedSchema = dir ? c->nOursSchema : c->nTheirsSchema;
    int i;
    for(i=0; i<nRenamed; i++){
      const char *zAnc = 0;
      const char **azNew;
      if( aRenamed[i].iTable<=1 ) continue;
      if( !mergeTableRenameOtherDrop(
            c->aAnc, c->nAnc, aDropped, nDropped, aRenamed, nRenamed,
            c->aAncSchema, c->nAncSchema,
            aRenamedSchema, nRenamedSchema, &aRenamed[i], &zAnc) ){
        continue;
      }
      if( !zAnc ) continue;
      azNew = sqlite3_realloc(
          (void*)pPolicy->azRenameOverDrop,
          (pPolicy->nRenameOverDrop + 1) * (int)sizeof(char*));
      if( !azNew ) return SQLITE_NOMEM;
      pPolicy->azRenameOverDrop = azNew;
      pPolicy->azRenameOverDrop[pPolicy->nRenameOverDrop++] = zAnc;
    }
  }
  return SQLITE_OK;
}

static int mergePass1CollectDualRename(
  MergePass1Ctx *c,
  MergeRowPolicy *pPolicy
){
  int i;
  for(i=0; i<c->nAnc; i++){
    struct TableEntry *pOurs;
    struct TableEntry *pTheirs;
    const char **azNew;
    if( c->aAnc[i].iTable<=1 || !c->aAnc[i].zName ) continue;
    pOurs = doltliteFindTableByNumber(c->aOurs, c->nOurs, c->aAnc[i].iTable);
    pTheirs = doltliteFindTableByNumber(c->aTheirs, c->nTheirs, c->aAnc[i].iTable);
    if( !pOurs || !pTheirs || !pOurs->zName || !pTheirs->zName ) continue;
    if( sqlite3_stricmp(pOurs->zName, c->aAnc[i].zName)==0 ) continue;
    if( sqlite3_stricmp(pTheirs->zName, c->aAnc[i].zName)==0 ) continue;
    if( sqlite3_stricmp(pOurs->zName, pTheirs->zName)==0 ) continue;
    azNew = sqlite3_realloc(
        (void*)pPolicy->azDualRename,
        (pPolicy->nDualRename + 1) * (int)sizeof(char*));
    if( !azNew ) return SQLITE_NOMEM;
    pPolicy->azDualRename = azNew;
    pPolicy->azDualRename[pPolicy->nDualRename++] = c->aAnc[i].zName;
  }
  return SQLITE_OK;
}

static void mergePass1FreeRowPolicy(MergeRowPolicy *pPolicy){
  sqlite3_free((void*)pPolicy->azRenameOverDrop);
  sqlite3_free((void*)pPolicy->azDualRename);
  pPolicy->azRenameOverDrop = 0;
  pPolicy->azDualRename = 0;
  pPolicy->nRenameOverDrop = 0;
  pPolicy->nDualRename = 0;
  pPolicy->nDeleteCompareFields = 0;
}

static int mergePass1IsAuxSchemaType(const char *zType){
  return zType && (strcmp(zType, "view")==0 || strcmp(zType, "trigger")==0);
}

static int mergePass1AuxSchemaSame(const SchemaEntry *pA, const SchemaEntry *pB){
  const char *zASql;
  const char *zBSql;
  const char *zATbl;
  const char *zBTbl;
  if( !pA || !pB ) return 0;
  zASql = pA->zSql ? pA->zSql : "";
  zBSql = pB->zSql ? pB->zSql : "";
  zATbl = pA->zTblName ? pA->zTblName : "";
  zBTbl = pB->zTblName ? pB->zTblName : "";
  return strcmp(zASql, zBSql)==0 && sqlite3_stricmp(zATbl, zBTbl)==0;
}

/* Views/triggers are catalog-only; competing defs are schema conflicts. */
static int mergePass1NoteAuxSchemaConflicts(MergePass1Ctx *c){
  int side, i, rc;

  for(side=0; side<2; side++){
    SchemaEntry *a = side==0 ? c->aOursSchema : c->aTheirsSchema;
    int n = side==0 ? c->nOursSchema : c->nTheirsSchema;
    for(i=0; i<n; i++){
      SchemaEntry *pOurs;
      SchemaEntry *pTheirs;
      const char *zName = a[i].zName;
      const char *zTable;
      int oursChanged;
      int theirsChanged;
      if( !mergePass1IsAuxSchemaType(a[i].zType) || !zName ) continue;
      if( side==1
       && findSchemaEntry(c->aOursSchema, c->nOursSchema, zName) ){
        continue;
      }
      pOurs = findSchemaEntry(c->aOursSchema, c->nOursSchema, zName);
      pTheirs = findSchemaEntry(c->aTheirsSchema, c->nTheirsSchema, zName);
      if( !pOurs && !pTheirs ) continue;
      if( pOurs && pTheirs && mergePass1AuxSchemaSame(pOurs, pTheirs) ){
        continue;
      }
      oursChanged = schemaEntryChangedByName(
          c->aAncSchema, c->nAncSchema, c->aOursSchema, c->nOursSchema, zName);
      theirsChanged = schemaEntryChangedByName(
          c->aAncSchema, c->nAncSchema, c->aTheirsSchema, c->nTheirsSchema,
          zName);
      if( !oursChanged || !theirsChanged ) continue;
      zTable = pOurs && pOurs->zTblName ? pOurs->zTblName
             : (pTheirs && pTheirs->zTblName ? pTheirs->zTblName : zName);
      rc = mergePass1NoteSchemaConflict(c, zTable, zName);
      if( rc!=SQLITE_OK ) return rc;
    }
  }
  return SQLITE_OK;
}

static int mergePass1MergeMaster(MergePass1Ctx *c, int iTable1Idx){
  struct TableEntry *ancEntry;
  struct TableEntry *theirsEntry;
  int bPreferOurMasterHere;
  int rc = SQLITE_OK;

  if( iTable1Idx < 0 ) return SQLITE_OK;

  ancEntry = doltliteFindTableByNumber(c->aAnc, c->nAnc, 1);
  theirsEntry = doltliteFindTableByNumber(c->aTheirs, c->nTheirs, 1);
  bPreferOurMasterHere = hasAnySchemaConflict(
      *c->ppConflictTables, *c->pnConflictTables)
      || (c->bPreferOurMaster
      && replayDropsDisjointSchemaObject(c->aAncSchema, c->nAncSchema,
                                         c->aTheirsSchema, c->nTheirsSchema));

  if( !ancEntry ){
    if( theirsEntry ){
      if( prollyHashCompare(&c->aOurs[iTable1Idx].root, &theirsEntry->root)!=0
       || prollyHashCompare(&c->aOurs[iTable1Idx].schemaHash,
                            &theirsEntry->schemaHash)!=0 ){
        return SQLITE_ERROR;
      }
    }
    c->aMerged[(*c->pnMerged)++] = c->aOurs[iTable1Idx];
    return SQLITE_OK;
  }
  if( !theirsEntry ){
    int oursChanged = prollyHashCompare(
        &c->aOurs[iTable1Idx].root, &ancEntry->root)!=0;
    if( oursChanged ) return SQLITE_ERROR;
    return SQLITE_OK;
  }

  {
    int oursChanged = prollyHashCompare(
        &c->aOurs[iTable1Idx].root, &ancEntry->root)!=0;
    int theirsChanged = prollyHashCompare(
        &theirsEntry->root, &ancEntry->root)!=0;
    int hasSchemaActions = (c->ppSchemaActions && c->pnSchemaActions
                            && *c->pnSchemaActions > 0);
    if( bPreferOurMasterHere ){
      c->aMerged[(*c->pnMerged)++] = c->aOurs[iTable1Idx];
      rc = mergePass1NoteAuxSchemaConflicts(c);
      if( rc!=SQLITE_OK ) return rc;
      return SQLITE_DONE;
    }
    if( oursChanged && theirsChanged
     && (hasSchemaActions || c->bDisjointSchemaChanges) ){
      c->aMerged[(*c->pnMerged)++] = c->aOurs[iTable1Idx];
      rc = mergePass1NoteAuxSchemaConflicts(c);
    }else if( oursChanged && theirsChanged ){
      ProllyHash mergedTableRoot;
      int nConflicts = 0;
      DoltliteConflictRow *aConflictRows = 0;
      int theirSchemaChanged2 = prollyHashCompare(
          &theirsEntry->schemaHash, &ancEntry->schemaHash)!=0;
      MergeRowPolicy policy;

      memset(&policy, 0, sizeof(policy));
      rc = mergePass1CollectRenameOverDrop(c, &policy);
      if( rc==SQLITE_OK ) rc = mergePass1CollectDualRename(c, &policy);
      if( rc!=SQLITE_OK ){
        mergePass1FreeRowPolicy(&policy);
        return rc;
      }
      rc = mergeTableRows(c->db, &ancEntry->root, &c->aOurs[iTable1Idx].root,
                          &theirsEntry->root, c->aOurs[iTable1Idx].flags,
                          ancEntry->flags, theirsEntry->flags,
                          &mergedTableRoot, &nConflicts, &aConflictRows,
                          NULL, 0, &policy);
      mergePass1FreeRowPolicy(&policy);
      if( rc!=SQLITE_OK ) return rc;

      {
        struct TableEntry merged = c->aOurs[iTable1Idx];
        memcpy(&merged.root, &mergedTableRoot, sizeof(ProllyHash));
        if( theirSchemaChanged2
         && prollyHashCompare(&c->aOurs[iTable1Idx].schemaHash,
                              &ancEntry->schemaHash)==0 ){
          memcpy(&merged.schemaHash, &theirsEntry->schemaHash,
                 sizeof(ProllyHash));
          merged.flags = theirsEntry->flags;
        }
        c->aMerged[(*c->pnMerged)++] = merged;
      }

      freeConflictRows(aConflictRows, nConflicts);
      rc = mergePass1NoteAuxSchemaConflicts(c);
      if( rc!=SQLITE_OK ) return rc;
      if( nConflicts>0
       && !hasAnySchemaConflict(*c->ppConflictTables, *c->pnConflictTables) ){
        int i;
        rc = SQLITE_OK;
        for(i=0; i<c->nAnc && rc==SQLITE_OK; i++){
          const char *zName = c->aAnc[i].zName;
          if( !zName || c->aAnc[i].iTable<=1 ) continue;
          if( !schemaEntryChangedByName(c->aAncSchema, c->nAncSchema,
                                        c->aOursSchema, c->nOursSchema, zName) ){
            continue;
          }
          if( !schemaEntryChangedByName(c->aAncSchema, c->nAncSchema,
                                        c->aTheirsSchema, c->nTheirsSchema,
                                        zName) ){
            continue;
          }
          if( hasSchemaConflictObject(*c->ppConflictTables,
                                      *c->pnConflictTables, zName) ){
            continue;
          }
          rc = mergePass1NoteSchemaConflict(c, zName, zName);
        }
      }
    }else if( theirsChanged ){
      struct TableEntry merged = c->aOurs[iTable1Idx];
      memcpy(&merged.root, &theirsEntry->root, sizeof(ProllyHash));
      memcpy(&merged.schemaHash, &theirsEntry->schemaHash, sizeof(ProllyHash));
      merged.flags = theirsEntry->flags;
      c->aMerged[(*c->pnMerged)++] = merged;
    }else{
      c->aMerged[(*c->pnMerged)++] = c->aOurs[iTable1Idx];
    }
  }
  return rc;
}

static void mergePass1ApplyIndexPatches(MergePass1Ctx *c){
  int ip, k;
  for(ip=0; ip<c->nPatches; ip++){
    for(k=0; k<*c->pnMerged; k++){
      if( c->aMerged[k].iTable==c->aPatches[ip].iTable ){
        memcpy(&c->aMerged[k].root, &c->aPatches[ip].mergedRoot,
               sizeof(ProllyHash));
        break;
      }
    }
  }
}

int mergeCatalogPass1(
  sqlite3 *db,
  struct TableEntry *aAnc, int nAnc,
  struct TableEntry *aOurs, int nOurs,
  struct TableEntry *aTheirs, int nTheirs,
  SchemaEntry *aAncSchema, int nAncSchema,
  SchemaEntry *aOursSchema, int nOursSchema,
  SchemaEntry *aTheirsSchema, int nTheirsSchema,
  struct TableEntry *aMerged, int *pnMerged,
  MergeConflictTable **ppConflictTables, int *pnConflictTables,
  int *pTotalConflicts,
  char **pzErrMsg,
  const ProllyHash *pCatAnc,
  const ProllyHash *pCatOurs,
  const ProllyHash *pCatTheirs,
  SchemaMergeAction **ppSchemaActions, int *pnSchemaActions,
  int bDisjointSchemaChanges,
  int bPreferOurMaster,
  int bBranchMerge,
  char ***pazReindex, int *pnReindex
){
  MergePass1Ctx c;
  int i, rc = SQLITE_OK;
  int iTable1Idx = -1;

  memset(&c, 0, sizeof(c));
  c.db = db;
  c.aAnc = aAnc; c.nAnc = nAnc;
  c.aOurs = aOurs; c.nOurs = nOurs;
  c.aTheirs = aTheirs; c.nTheirs = nTheirs;
  c.aAncSchema = aAncSchema; c.nAncSchema = nAncSchema;
  c.aOursSchema = aOursSchema; c.nOursSchema = nOursSchema;
  c.aTheirsSchema = aTheirsSchema; c.nTheirsSchema = nTheirsSchema;
  c.aMerged = aMerged; c.pnMerged = pnMerged;
  c.ppConflictTables = ppConflictTables;
  c.pnConflictTables = pnConflictTables;
  c.pTotalConflicts = pTotalConflicts;
  c.pzErrMsg = pzErrMsg;
  c.pCatAnc = pCatAnc; c.pCatOurs = pCatOurs; c.pCatTheirs = pCatTheirs;
  c.ppSchemaActions = ppSchemaActions; c.pnSchemaActions = pnSchemaActions;
  c.bDisjointSchemaChanges = bDisjointSchemaChanges;
  c.bPreferOurMaster = bPreferOurMaster;
  c.bBranchMerge = bBranchMerge;
  c.pazReindex = pazReindex; c.pnReindex = pnReindex;

  rc = mergePass1CheckIndexOverRenamedColumn(&c);
  if( rc==SQLITE_OK ) rc = mergePass1CheckTriggerOverRenamedTable(&c);
  if( rc==SQLITE_OK ) rc = mergePass1CheckRowEditOfDroppedColumn(&c);
  if( rc==SQLITE_OK ) rc = mergePass1CheckDuplicateIndexColumns(&c);
  if( rc==SQLITE_OK ) rc = mergePass1CheckDependentOverDualRename(&c);
  if( rc!=SQLITE_OK ){
    mergePass1Free(&c);
    return rc;
  }

  for(i=0; i<nOurs; i++){
    if( aOurs[i].iTable==1 ){
      iTable1Idx = i;
      continue;
    }
    rc = mergePass1MergeOursEntry(&c, i);
    if( rc!=SQLITE_OK ){
      mergePass1Free(&c);
      return rc;
    }
  }

  /* Record theirs-surviving conflicts before choosing the master root. */
  rc = mergePass1TheirsModifyDelete(&c);
  if( rc!=SQLITE_OK ){
    mergePass1Free(&c);
    return rc;
  }

  rc = mergePass1MergeMaster(&c, iTable1Idx);
  if( rc==SQLITE_DONE ){
    mergePass1Free(&c);
    return SQLITE_OK;
  }
  if( rc!=SQLITE_OK ){
    mergePass1Free(&c);
    return rc;
  }

  /* Inline index roots already include row conflicts. */
  mergePass1ApplyIndexPatches(&c);
  mergePass1Free(&c);
  return rc;
}

#endif

/************** End of doltlite_merge_pass1.c ********************************/
/************** Begin file doltlite_merge_pass2.c ****************************/
#ifdef DOLTLITE_PROLLY

/* #include "doltlite_merge_int.h" */

static const char *mergeIndexSkipQuoted(const char *z, char q){
  char qEnd = (q=='[') ? ']' : q;
  z++;
  while( *z ){
    if( q!='[' && *z==q && z[1]==q ){ z += 2; continue; }
    if( *z==qEnd ) return z+1;
    z++;
  }
  return z;
}

static const char *mergeIndexSkipName(const char *z, const char *zEnd){
  while( z<zEnd && sqlite3Isspace(*z) ) z++;
  if( z>=zEnd ) return z;
  if( *z=='\'' || *z=='"' || *z=='`' || *z=='[' ) return mergeIndexSkipQuoted(z, *z);
  if( sqlite3Isalnum(*z) || *z=='_' || *z=='$' ){
    z++;
    while( z<zEnd && (sqlite3Isalnum(*z) || *z=='_' || *z=='$') ) z++;
  }
  return z;
}

static int mergeIndexIsSortKeyword(const char *z, int n){
  static const char *const azKw[] = {
    "ASC", "COLLATE", "DESC", "FIRST", "LAST", "NULLS"
  };
  int i;
  for(i=0; i<(int)(sizeof(azKw)/sizeof(azKw[0])); i++){
    if( sqlite3_strnicmp(z, azKw[i], n)==0 && azKw[i][n]==0 ) return 1;
  }
  return 0;
}

static char *mergeIndexDupIdent(const char *z, int n){
  char *zOut = n>0 ? sqlite3_malloc(n+1) : 0;
  if( zOut ){ memcpy(zOut, z, n); zOut[n] = 0; }
  return zOut;
}

static int mergeIndexEachColumn(
  const char *zIndexSql,
  int (*xEach)(void*, const char*),
  void *pCtx
){
  const char *zOpen = zIndexSql ? strchr(zIndexSql, '(') : 0;
  const char *zEnd, *z, *zIdent, *zLook;
  char *zCol;
  int depth, nIdent, rc = SQLITE_OK;

  if( !zOpen ) return SQLITE_OK;
  depth = 1;
  zEnd = zOpen + 1;
  while( *zEnd && depth>0 ){
    if( *zEnd=='\'' || *zEnd=='"' || *zEnd=='`' || *zEnd=='[' ){
      zEnd = mergeIndexSkipQuoted(zEnd, *zEnd);
      continue;
    }
    if( *zEnd=='(' ) depth++;
    else if( *zEnd==')' ) depth--;
    if( depth>0 ) zEnd++;
  }
  if( depth!=0 ) return SQLITE_OK;

  z = zOpen + 1;
  zEnd = zIndexSql + strlen(zIndexSql);
  while( z<zEnd && rc==SQLITE_OK ){
    if( *z=='\'' ){ z = mergeIndexSkipQuoted(z, '\''); continue; }
    if( *z=='"' || *z=='`' || *z=='[' ){
      zIdent = z;
      z = mergeIndexSkipQuoted(z, *z);
      zCol = mergeIndexDupIdent(zIdent, (int)(z-zIdent));
      if( !zCol ) return SQLITE_NOMEM;
      sqlite3Dequote(zCol);
      if( zCol[0] ) rc = xEach(pCtx, zCol);
      sqlite3_free(zCol);
      continue;
    }
    if( !(sqlite3Isalnum(*z) || *z=='_' || *z=='$') ){ z++; continue; }
    zIdent = z++;
    while( z<zEnd && (sqlite3Isalnum(*z) || *z=='_' || *z=='$') ) z++;
    nIdent = (int)(z-zIdent);
    zLook = z;
    while( zLook<zEnd && sqlite3Isspace(*zLook) ) zLook++;
    if( zLook<zEnd && *zLook=='(' ) continue;
    if( mergeIndexIsSortKeyword(zIdent, nIdent) ){
      if( nIdent==7 && sqlite3_strnicmp(zIdent, "COLLATE", 7)==0 ){
        z = mergeIndexSkipName(z, zEnd);
      }
      continue;
    }
    zCol = mergeIndexDupIdent(zIdent, nIdent);
    if( !zCol ) return SQLITE_NOMEM;
    rc = xEach(pCtx, zCol);
    sqlite3_free(zCol);
  }
  return rc;
}

typedef struct MergeIndexColCtx MergeIndexColCtx;
struct MergeIndexColCtx {
  ParsedColumn *aAnc; int nAnc;
  ParsedColumn *aSide; int nSide;
  char *zMissing;
};

static int mergeIndexColSurvives(void *pCtx, const char *zCol){
  MergeIndexColCtx *p = (MergeIndexColCtx*)pCtx;
  int iAnc;
  if( p->zMissing ) return SQLITE_OK;
  if( parsedColumnIndexByName(p->aSide, p->nSide, zCol)>=0 ) return SQLITE_OK;
  /* Other side added it; merge carries additions. */
  iAnc = parsedColumnIndexByName(p->aAnc, p->nAnc, zCol);
  if( iAnc<0 ) return SQLITE_OK;
  /* Same position, same definition: a rename, not a drop. Index
  ** retarget is not expressible here yet. */
  if( iAnc<p->nSide
   && parsedColumnIndexByName(p->aAnc, p->nAnc, p->aSide[iAnc].zName)<0
   && parsedColumnDefinitionsMatch(&p->aSide[iAnc], &p->aAnc[iAnc]) ){
    return SQLITE_OK;
  }
  p->zMissing = sqlite3_mprintf("%s", zCol);
  return p->zMissing ? SQLITE_OK : SQLITE_NOMEM;
}

static int mergeIndexColRenamed(void *pCtx, const char *zCol){
  MergeIndexColCtx *p = (MergeIndexColCtx*)pCtx;
  int iAnc;
  if( p->zMissing ) return SQLITE_OK;
  if( parsedColumnIndexByName(p->aSide, p->nSide, zCol)>=0 ) return SQLITE_OK;
  iAnc = parsedColumnIndexByName(p->aAnc, p->nAnc, zCol);
  if( iAnc<0 ) return SQLITE_OK;
  if( iAnc<p->nSide
   && parsedColumnIndexByName(p->aAnc, p->nAnc, p->aSide[iAnc].zName)<0
   && parsedColumnDefinitionsMatch(&p->aSide[iAnc], &p->aAnc[iAnc]) ){
    p->zMissing = sqlite3_mprintf("%s", zCol);
    return p->zMissing ? SQLITE_OK : SQLITE_NOMEM;
  }
  return SQLITE_OK;
}

static int mergeIndexColumnScan(
  const char *zIndexSql,
  const char *zAncTableSql,
  const char *zSideTableSql,
  int (*xEach)(void*, const char*),
  char **pzColumn
){
  MergeIndexColCtx ctx;
  int rc;

  if( pzColumn ) *pzColumn = 0;
  if( !zIndexSql || !zAncTableSql || !zSideTableSql ) return 0;
  memset(&ctx, 0, sizeof(ctx));
  if( parseColumns(zAncTableSql, &ctx.aAnc, &ctx.nAnc)!=SQLITE_OK ) return 0;
  if( parseColumns(zSideTableSql, &ctx.aSide, &ctx.nSide)!=SQLITE_OK ){
    freeColumns(ctx.aAnc, ctx.nAnc);
    return 0;
  }
  rc = mergeIndexEachColumn(zIndexSql, xEach, &ctx);
  freeColumns(ctx.aAnc, ctx.nAnc);
  freeColumns(ctx.aSide, ctx.nSide);
  if( rc!=SQLITE_OK || !ctx.zMissing ){
    sqlite3_free(ctx.zMissing);
    return 0;
  }
  if( pzColumn ){
    *pzColumn = ctx.zMissing;
  }else{
    sqlite3_free(ctx.zMissing);
  }
  return 1;
}

typedef struct MergeIndexNameList MergeIndexNameList;
struct MergeIndexNameList { char **az; int n; };

static int mergeIndexCollectName(void *pCtx, const char *zCol){
  MergeIndexNameList *p = (MergeIndexNameList*)pCtx;
  char **azNew = sqlite3_realloc(p->az, (p->n+1)*(int)sizeof(char*));
  if( !azNew ) return SQLITE_NOMEM;
  p->az = azNew;
  p->az[p->n] = sqlite3_mprintf("%s", zCol);
  if( !p->az[p->n] ) return SQLITE_NOMEM;
  p->n++;
  return SQLITE_OK;
}

static void mergeIndexNameListFree(MergeIndexNameList *p){
  int i;
  for(i=0; i<p->n; i++) sqlite3_free(p->az[i]);
  sqlite3_free(p->az);
}

int mergeIndexColumnsOverlap(const char *zSqlA, const char *zSqlB){
  MergeIndexNameList a;
  MergeIndexNameList b;
  int i, j, bOverlap = 0;

  if( !zSqlA || !zSqlB ) return 0;
  memset(&a, 0, sizeof(a));
  memset(&b, 0, sizeof(b));
  if( mergeIndexEachColumn(zSqlA, mergeIndexCollectName, &a)==SQLITE_OK
   && mergeIndexEachColumn(zSqlB, mergeIndexCollectName, &b)==SQLITE_OK ){
    for(i=0; i<a.n && !bOverlap; i++){
      for(j=0; j<b.n && !bOverlap; j++){
        if( sqlite3_stricmp(a.az[i], b.az[j])==0 ) bOverlap = 1;
      }
    }
  }
  mergeIndexNameListFree(&a);
  mergeIndexNameListFree(&b);
  return bOverlap;
}

/* Dual added indexes over a shared column: Dolt reports a conflict;
** keeping both would impose one side's uniqueness on the other. */
int mergePreDetectDualIndexOverlap(
  SchemaEntry *aAnc, int nAnc,
  SchemaEntry *aOurs, int nOurs,
  SchemaEntry *aTheirs, int nTheirs,
  MergeConflictTable **ppConflictTables,
  int *pnConflictTables,
  int *pTotalConflicts
){
  int i, j, rc;

  for(i=0; i<nOurs; i++){
    if( !aOurs[i].zType || strcmp(aOurs[i].zType, "index")!=0 ) continue;
    if( !aOurs[i].zName || !aOurs[i].zSql || !aOurs[i].zTblName ) continue;
    if( findSchemaEntry(aAnc, nAnc, aOurs[i].zName) ) continue;
    for(j=0; j<nTheirs; j++){
      int added = 0;
      if( !aTheirs[j].zType || strcmp(aTheirs[j].zType, "index")!=0 ) continue;
      if( !aTheirs[j].zName || !aTheirs[j].zSql || !aTheirs[j].zTblName ) continue;
      if( findSchemaEntry(aAnc, nAnc, aTheirs[j].zName) ) continue;
      if( sqlite3_stricmp(aOurs[i].zName, aTheirs[j].zName)==0 ) continue;
      if( sqlite3_stricmp(aOurs[i].zTblName, aTheirs[j].zTblName)!=0 ) continue;
      if( !mergeIndexColumnsOverlap(aOurs[i].zSql, aTheirs[j].zSql) ) continue;
      rc = appendSchemaConflict(ppConflictTables, pnConflictTables,
                                aOurs[i].zTblName, aOurs[i].zName, &added);
      if( rc!=SQLITE_OK ) return rc;
      if( pTotalConflicts ) *pTotalConflicts += added;
      break;
    }
  }
  return SQLITE_OK;
}

int mergeIndexColumnRenamedAway(
  const char *zIndexSql,
  const char *zAncTableSql,
  const char *zSideTableSql,
  char **pzColumn
){
  return mergeIndexColumnScan(zIndexSql, zAncTableSql, zSideTableSql,
                              mergeIndexColRenamed, pzColumn);
}

int mergeIndexColumnGoneFrom(
  const char *zIndexSql,
  const char *zAncTableSql,
  const char *zSideTableSql,
  char **pzColumn
){
  MergeIndexColCtx ctx;
  int rc;

  if( pzColumn ) *pzColumn = 0;
  if( !zIndexSql || !zAncTableSql || !zSideTableSql ) return 0;

  memset(&ctx, 0, sizeof(ctx));
  if( parseColumns(zAncTableSql, &ctx.aAnc, &ctx.nAnc)!=SQLITE_OK ) return 0;
  if( parseColumns(zSideTableSql, &ctx.aSide, &ctx.nSide)!=SQLITE_OK ){
    freeColumns(ctx.aAnc, ctx.nAnc);
    return 0;
  }

  rc = mergeIndexEachColumn(zIndexSql, mergeIndexColSurvives, &ctx);
  freeColumns(ctx.aAnc, ctx.nAnc);
  freeColumns(ctx.aSide, ctx.nSide);
  if( rc!=SQLITE_OK || !ctx.zMissing ){
    sqlite3_free(ctx.zMissing);
    return 0;
  }
  if( pzColumn ){
    *pzColumn = ctx.zMissing;
  }else{
    sqlite3_free(ctx.zMissing);
  }
  return 1;
}


int mergeCatalogPass2(
  struct TableEntry *aAnc, int nAnc,
  struct TableEntry *aOurs, int nOurs,
  struct TableEntry *aTheirs, int nTheirs,
  SchemaEntry *aAncSchema, int nAncSchema,
  SchemaEntry *aOursSchema, int nOursSchema,
  SchemaEntry *aTheirsSchema, int nTheirsSchema,
  struct TableEntry *aMerged, int *pnMerged,
  Pgno *piNextMerged,
  int bDisjointSchemaChanges,
  MergeConflictTable *aConflictTables,
  int nConflictTables,
  SchemaRootpageRemap **ppaRemap,
  int *pnRemap,
  char ***pazReindex,
  int *pnReindex
){
  int i, rc = SQLITE_OK;

  for(i=0; i<nTheirs; i++){
    const char *zName = aTheirs[i].zName;
    struct TableEntry *oursEntry;

    if( aTheirs[i].iTable<=1 ) continue;

    if( !zName ){
      SchemaEntry *pTheirSe = findSchemaEntryByRootpage(
          aTheirsSchema, nTheirsSchema, aTheirs[i].iTable);
      if( pTheirSe && pTheirSe->zName && pTheirSe->zType
       && strcmp(pTheirSe->zType, "index")==0 ){
        SchemaEntry *pAncSe = findSchemaEntry(
            aAncSchema, nAncSchema, pTheirSe->zName);
        SchemaEntry *pOurSe = findSchemaEntry(
            aOursSchema, nOursSchema, pTheirSe->zName);
        struct TableEntry *pTheirTable = doltliteFindTableByName(
            aTheirs, nTheirs, pTheirSe->zTblName);
        if( hasSchemaConflictObject(aConflictTables, nConflictTables,
                                    pTheirSe->zName)
         || hasSchemaConflictObject(aConflictTables, nConflictTables,
                                    pTheirSe->zTblName)
         || hasSchemaConflictTable(aConflictTables, nConflictTables,
                                   pTheirSe->zTblName)
         || !pTheirTable
         || !doltliteFindTableByName(aMerged, *pnMerged,
                                     pTheirSe->zTblName)
         ){
          continue;
        }
        if( mergeIndexFollowsDualRename(
              aAncSchema, nAncSchema, aOursSchema, nOursSchema,
              aTheirsSchema, nTheirsSchema, pAncSe, pOurSe, pTheirSe) ){
          continue;
        }
        /* Index over a column we dropped or renamed cannot load.
        ** Dolt drops it with the column. */
        {
          SchemaEntry *pAncTbl = findSchemaEntry(
              aAncSchema, nAncSchema, pTheirSe->zTblName);
          SchemaEntry *pOurTbl = findSchemaEntry(
              aOursSchema, nOursSchema, pTheirSe->zTblName);
          char *zGone = 0;
          if( pAncTbl && pOurTbl
           && mergeIndexColumnGoneFrom(pTheirSe->zSql, pAncTbl->zSql,
                                           pOurTbl->zSql, &zGone) ){
            sqlite3_free(zGone);
            continue;
          }
          sqlite3_free(zGone);
        }
        oursEntry = findCatalogEntryBySchemaObject(
            aOurs, nOurs, aOursSchema, nOursSchema,
            pTheirSe->zType, pTheirSe->zName, pTheirSe->zTblName);
        if( oursEntry ) continue;

        {
          struct TableEntry *ancEntry = findCatalogEntryBySchemaObject(
              aAnc, nAnc, aAncSchema, nAncSchema,
              pTheirSe->zType, pTheirSe->zName, pTheirSe->zTblName);
          if( !ancEntry ){
            struct TableEntry newEntry = aTheirs[i];
            int j, conflict = 0;
            Pgno oldPg = newEntry.iTable;
            int forceRemap = bDisjointSchemaChanges;
            for(j=0; j<*pnMerged; j++){
              if( aMerged[j].iTable==newEntry.iTable ){
                conflict = 1;
                break;
              }
            }
            if( conflict || forceRemap ){
              SchemaRootpageRemap *aNew;
              int nOld = *pnRemap;
              newEntry.iTable = (*piNextMerged)++;
              aNew = sqlite3_realloc(*ppaRemap,
                                     (nOld+1)*(int)sizeof(SchemaRootpageRemap));
              if( !aNew ) return SQLITE_NOMEM;
              *ppaRemap = aNew;
              aNew[nOld].oldPg = oldPg;
              aNew[nOld].newPg = newEntry.iTable;
              *pnRemap = nOld + 1;
            }
            if( newEntry.iTable >= *piNextMerged ) *piNextMerged = newEntry.iTable + 1;
            aMerged[(*pnMerged)++] = newEntry;
            /* Adopted tree is theirs-only; rebuild over merged rows. */
            rc = mergeAppendReindexName(pazReindex, pnReindex, pTheirSe->zName);
            if( rc!=SQLITE_OK ) return rc;
          }else if( schemaEntryChangedByName(
                        aAncSchema, nAncSchema,
                        aTheirsSchema, nTheirsSchema,
                        pTheirSe->zName) ){
            struct TableEntry newEntry = aTheirs[i];
            int j, conflict = 0;
            Pgno oldPg = newEntry.iTable;
            for(j=0; j<*pnMerged; j++){
              if( aMerged[j].iTable==newEntry.iTable ){
                conflict = 1;
                break;
              }
            }
            if( conflict ){
              SchemaRootpageRemap *aNew;
              int nOld = *pnRemap;
              newEntry.iTable = (*piNextMerged)++;
              aNew = sqlite3_realloc(*ppaRemap,
                  (nOld+1)*(int)sizeof(SchemaRootpageRemap));
              if( !aNew ) return SQLITE_NOMEM;
              *ppaRemap = aNew;
              aNew[nOld].oldPg = oldPg;
              aNew[nOld].newPg = newEntry.iTable;
              *pnRemap = nOld + 1;
            }
            if( newEntry.iTable >= *piNextMerged ){
              *piNextMerged = newEntry.iTable + 1;
            }
            aMerged[(*pnMerged)++] = newEntry;
            rc = mergeAppendReindexName(pazReindex, pnReindex, pTheirSe->zName);
            if( rc!=SQLITE_OK ) return rc;
          }else{
            /* Unmodified index does not override our DROP. */
          }
        }
        continue;
      }

      if( !doltliteFindTableByNumber(aOurs, nOurs, aTheirs[i].iTable) ){
        struct TableEntry newEntry = aTheirs[i];
        int j, conflict = 0;
        Pgno oldPg = newEntry.iTable;
        int forceRemap = bDisjointSchemaChanges;
        for(j=0; j<*pnMerged; j++){
          if( aMerged[j].iTable==newEntry.iTable ){
            conflict = 1;
            break;
          }
        }
        if( conflict || forceRemap ){
          SchemaRootpageRemap *aNew;
          int nOld = *pnRemap;
          Pgno newPg = *piNextMerged;
          aNew = sqlite3_realloc(*ppaRemap,
                                 (nOld+1)*(int)sizeof(SchemaRootpageRemap));
          if( !aNew ) return SQLITE_NOMEM;
          *ppaRemap = aNew;
          aNew[nOld].oldPg = oldPg;
          aNew[nOld].newPg = newPg;
          *pnRemap = nOld + 1;
          newEntry.iTable = newPg;
          (*piNextMerged)++;
        }
        if( newEntry.iTable >= *piNextMerged ) *piNextMerged = newEntry.iTable + 1;
        aMerged[(*pnMerged)++] = newEntry;
      }else if( bDisjointSchemaChanges ){
        struct TableEntry *oursIdx = doltliteFindTableByNumber(aOurs, nOurs, aTheirs[i].iTable);
        struct TableEntry *ancIdx = doltliteFindTableByNumber(aAnc, nAnc, aTheirs[i].iTable);
        if( oursIdx && !ancIdx
         && (prollyHashCompare(&oursIdx->root, &aTheirs[i].root)!=0
             || prollyHashCompare(&oursIdx->schemaHash, &aTheirs[i].schemaHash)!=0) ){
          struct TableEntry newEntry = aTheirs[i];
          SchemaRootpageRemap *aNew;
          int nOld = *pnRemap;
          Pgno newPg = *piNextMerged;
          aNew = sqlite3_realloc(*ppaRemap,
                                 (nOld+1)*(int)sizeof(SchemaRootpageRemap));
          if( !aNew ) return SQLITE_NOMEM;
          *ppaRemap = aNew;
          aNew[nOld].oldPg = aTheirs[i].iTable;
          aNew[nOld].newPg = newPg;
          *pnRemap = nOld + 1;
          newEntry.iTable = newPg;
          (*piNextMerged)++;
          aMerged[(*pnMerged)++] = newEntry;
        }
      }
      continue;
    }

    if( hasSchemaConflictObject(aConflictTables, nConflictTables, zName) ){
      continue;
    }
    oursEntry = doltliteFindTableByName(aOurs, nOurs, zName);
    if( oursEntry ) continue;
    {
      struct TableEntry *pOursSame = doltliteFindTableByNumber(
          aOurs, nOurs, aTheirs[i].iTable);
      struct TableEntry *pAncSame = doltliteFindTableByNumber(
          aAnc, nAnc, aTheirs[i].iTable);
      if( pOursSame && zName && pAncSame && pAncSame->zName
       && strcmp(zName, pAncSame->zName)==0 ){
        continue;
      }
      if( pOursSame && pOursSame->zName && zName
       && strcmp(pOursSame->zName, zName)==0 ){
        continue;
      }
    }

    {
      struct TableEntry *ancEntry = doltliteFindTableByName(aAnc, nAnc, zName);
      if( !ancEntry ){

        struct TableEntry newEntry = aTheirs[i];
        int forceRemap = bDisjointSchemaChanges;
        {
          int j, conflict = 0;
          for(j=0; j<*pnMerged; j++){
            if( aMerged[j].iTable==newEntry.iTable ){ conflict = 1; break; }
          }
          if( conflict || forceRemap ) newEntry.iTable = (*piNextMerged)++;
        }
        if( newEntry.iTable >= *piNextMerged ) *piNextMerged = newEntry.iTable + 1;

        newEntry.zName = sqlite3_mprintf("%s", zName);
        aMerged[(*pnMerged)++] = newEntry;
      }else{

        int theirsChanged = prollyHashCompare(&aTheirs[i].root, &ancEntry->root)!=0;
        if( theirsChanged ){
          return SQLITE_ERROR;
        }

      }
    }
  }
  return SQLITE_OK;
}

/* Contentless FTS has no source to rebuild from; fts5 refuses 'rebuild'. */
static int mergeFtsIsContentless(Table *pTab){
  int i;
  for(i=3; i<pTab->u.vtab.nArg; i++){
    const char *z = pTab->u.vtab.azArg[i];
    const char *zEq;
    if( !z ) continue;
    while( *z==' ' ) z++;
    if( sqlite3_strnicmp(z, "content", 7)!=0 ) continue;
    zEq = &z[7];
    while( *zEq==' ' ) zEq++;
    if( *zEq!='=' ) continue;
    zEq++;
    while( *zEq==' ' ) zEq++;
    /* content='' is contentless; content='x' is not. */
    if( (zEq[0]=='\'' && zEq[1]=='\'') || (zEq[0]=='"' && zEq[1]=='"')
     || zEq[0]==0 ){
      return 1;
    }
    return 0;
  }
  return 0;
}

/* Derived shadow of a vtab (not %_content/%_base). Sets *pbRebuildable
** if the owner can regenerate it. Authoritative shadows stay loud. */
static char *mergeDerivedShadowOwner(
  sqlite3 *db,
  const char *zTable,
  int *pbRebuildable
){
  static const char *azSuffix[] = {
    /* vec1 */   "_idx", "_meta", "_model", "_config",
    /* fts5 */   "_data", "_docsize",
    /* fts3/4 */ "_segments", "_segdir", "_stat",
    /* rtree */  "_node", "_parent", "_rowid"
  };
  unsigned int i;
  size_t nTable = strlen(zTable);

  *pbRebuildable = 0;
  for(i=0; i<sizeof(azSuffix)/sizeof(azSuffix[0]); i++){
    size_t nSfx = strlen(azSuffix[i]);
    const char *zModule;
    char *zOwner;
    Table *pTab;
    if( nTable<=nSfx || strcmp(&zTable[nTable-nSfx], azSuffix[i])!=0 ){
      continue;
    }
    zOwner = sqlite3_mprintf("%.*s", (int)(nTable-nSfx), zTable);
    if( !zOwner ) return 0;
    pTab = sqlite3FindTable(db, zOwner, "main");
    if( !pTab || !IsVirtual(pTab) || pTab->u.vtab.nArg<=0
     || !sqlite3IsShadowTableOf(db, pTab, zTable) ){
      sqlite3_free(zOwner);
      return 0;
    }
    zModule = pTab->u.vtab.azArg[0];

    if( sqlite3_stricmp(zModule, "fts5")==0
     || sqlite3_stricmp(zModule, "fts4")==0
     || sqlite3_stricmp(zModule, "fts3")==0 ){
      /* Rebuild from merged content; contentless has none. */
      *pbRebuildable = !mergeFtsIsContentless(pTab);
      return zOwner;
    }
    if( sqlite3_stricmp(zModule, "rtree")==0
     || sqlite3_stricmp(zModule, "rtree_i32")==0 ){
      /* r-tree coordinates live in %_node; no rebuild. */
      *pbRebuildable = 0;
      return zOwner;
    }
    if( sqlite3_stricmp(zModule, "vec1")!=0 ){
      sqlite3_free(zOwner);
      return 0;
    }
    {
      /* Rebuild only if %_base holds raw vectors and the model row
      ** is present. A NULL rebuild arg keeps cached state. Uncompressed
      ** %_base stores buckets, not vectors; auto-resolve would drop them. */
      char *zQry = sqlite3_mprintf(
          "SELECT (SELECT count(*) FROM \"%w_base\""
          "         WHERE typeof(vector)!='blob')=0"
          " AND EXISTS(SELECT 1 FROM \"%w_model\""
          "             WHERE id=1 AND typeof(val)='blob' AND length(val)>0)",
          zOwner, zOwner);
      sqlite3_stmt *pStmt = 0;
      int bEligible = 0;
      if( zQry && sqlite3_prepare_v2(db, zQry, -1, &pStmt, 0)==SQLITE_OK ){
        bEligible = sqlite3_step(pStmt)==SQLITE_ROW
                 && sqlite3_column_int(pStmt, 0)==1;
      }
      sqlite3_finalize(pStmt);
      sqlite3_free(zQry);
      if( bEligible ){
        *pbRebuildable = 1;
        return zOwner;
      }
      /* Ineligible vec1 stays resolvable; not reported as derived. */
      sqlite3_free(zOwner);
      return 0;
    }
  }
  return 0;
}

/* If every conflict is a rebuildable derived shadow, drop them and
** return owners to rebuild. Any non-derived conflict keeps all loud. */
int mergeFilterDerivedShadowConflicts(
  sqlite3 *db,
  MergeConflictTable *aConflictTables,
  int *pnConflictTables,
  int *pTotalConflicts,
  char ***pazRebuild,
  int *pnRebuild,
  char **pzRefuse
){
  int i, j, rc = SQLITE_OK;
  char **azOwner = 0;

  azOwner = sqlite3_malloc((*pnConflictTables)*(int)sizeof(char*));
  if( !azOwner ) return SQLITE_NOMEM;
  memset(azOwner, 0, (*pnConflictTables)*sizeof(char*));

  for(i=0; i<*pnConflictTables; i++){
    int bRebuildable = 0;
    if( aConflictTables[i].nSchemaObjects>0
     || aConflictTables[i].nConflicts<=0
     || (azOwner[i] = mergeDerivedShadowOwner(
            db, aConflictTables[i].zName, &bRebuildable))==0 ){
      doltliteFreeNameList(azOwner, *pnConflictTables);
      return SQLITE_OK;
    }
    if( !bRebuildable ){
      /* Neither resolution is valid: the discarded side cannot be
      ** regenerated. Refuse rather than commit a disagreeing index. */
      if( pzRefuse && *pzRefuse==0 ){
        *pzRefuse = sqlite3_mprintf(
            "cannot merge: '%s' indexes data that cannot be rebuilt from the "
            "merged rows, and both sides changed it. Merge on one branch, or "
            "drop and recreate '%s' after merging",
            azOwner[i], azOwner[i]);
      }
      doltliteFreeNameList(azOwner, *pnConflictTables);
      return SQLITE_OK;
    }
  }

  for(i=0; i<*pnConflictTables && rc==SQLITE_OK; i++){
    int seen = 0;
    for(j=0; j<i; j++){
      if( strcmp(azOwner[j], azOwner[i])==0 ){ seen = 1; break; }
    }
    if( !seen ){
      rc = mergeAppendReindexName(pazRebuild, pnRebuild, azOwner[i]);
    }
  }
  doltliteFreeNameList(azOwner, *pnConflictTables);
  if( rc!=SQLITE_OK ) return rc;

  for(i=0; i<*pnConflictTables; i++){
    sqlite3_free(aConflictTables[i].zName);
    aConflictTables[i].zName = 0;
    freeConflictRows(aConflictTables[i].aRows, aConflictTables[i].nConflicts);
    aConflictTables[i].aRows = 0;
    aConflictTables[i].nConflicts = 0;
  }
  *pnConflictTables = 0;
  *pTotalConflicts = 0;
  return SQLITE_OK;
}

#endif

/************** End of doltlite_merge_pass2.c ********************************/
/************** Begin file doltlite_merge_predetect.c ************************/
#ifdef DOLTLITE_PROLLY

/* #include "doltlite_merge_int.h" */

/* Schema-level refusals, before pass 1 mutates anything. */

/* Bare column-name keys only. Expression, partial, COLLATE, or sort
** order make two indexes different; those are not compared. */
static int mergeIndexPlainKey(const char *zSql, char ***pazCol, int *pnCol){
  const char *zOpen, *zClose, *z;
  char **az = 0;
  int n = 0, i;

  *pazCol = 0;
  *pnCol = 0;
  if( !zSql ) return 0;
  zOpen = strchr(zSql, '(');
  if( !zOpen ) return 0;
  for(zClose=zOpen+1; *zClose && *zClose!=')'; zClose++){
    /* Nested paren: function or parenthesised expression. */
    if( *zClose=='(' ) return 0;
  }
  if( *zClose!=')' ) return 0;
  for(z=zClose+1; *z; z++){
    if( !sqlite3Isspace(*z) && *z!=';' ) return 0;
  }
  z = zOpen + 1;
  while( z<zClose ){
    const char *zTok;
    int nTok;
    while( z<zClose && (sqlite3Isspace(*z) || *z==',') ) z++;
    if( z>=zClose ) break;
    zTok = z;
    while( z<zClose && *z!=',' ) z++;
    nTok = (int)(z-zTok);
    while( nTok>0 && sqlite3Isspace(zTok[nTok-1]) ) nTok--;
    if( nTok<=0 ) goto plain_key_fail;
    for(i=0; i<nTok; i++){
      /* ASC, COLLATE, or a quoted form is not a safe comparison. */
      if( !(sqlite3Isalnum(zTok[i]) || zTok[i]=='_' || zTok[i]=='$') ){
        goto plain_key_fail;
      }
    }
    {
      char **azNew = sqlite3_realloc(az, (n+1)*(int)sizeof(char*));
      if( !azNew ) goto plain_key_fail;
      az = azNew;
      az[n] = sqlite3_mprintf("%.*s", nTok, zTok);
      if( !az[n] ) goto plain_key_fail;
      n++;
    }
  }
  if( n==0 ) goto plain_key_fail;
  *pazCol = az;
  *pnCol = n;
  return 1;

plain_key_fail:
  for(i=0; i<n; i++) sqlite3_free(az[i]);
  sqlite3_free(az);
  return 0;
}

static int mergeIndexSameKey(const char *zSqlA, const char *zSqlB){
  char **azA = 0, **azB = 0;
  int nA = 0, nB = 0, i, same = 0;

  if( mergeIndexPlainKey(zSqlA, &azA, &nA)
   && mergeIndexPlainKey(zSqlB, &azB, &nB)
   && nA==nB ){
    same = 1;
    for(i=0; i<nA && same; i++){
      if( sqlite3_stricmp(azA[i], azB[i])!=0 ) same = 0;
    }
  }
  for(i=0; i<nA; i++) sqlite3_free(azA[i]);
  for(i=0; i<nB; i++) sqlite3_free(azB[i]);
  sqlite3_free(azA);
  sqlite3_free(azB);
  return same;
}

/* One side added an index over columns another index already covers.
** Dolt refuses ("cannot be merged"): keeping both would impose one
** side's uniqueness. Solo additions are the user's business. */
int mergePass1CheckDuplicateIndexColumns(MergePass1Ctx *c){
  int side, i, j;

  /* Merge only. Replay (revert/cherry-pick/rebase) has one intended
  ** result; refusing would also reject restoring a prior state. */
  if( !c->bBranchMerge ) return SQLITE_OK;

  for(side=0; side<2; side++){
    SchemaEntry *aNew = side ? c->aTheirsSchema : c->aOursSchema;
    int nNew = side ? c->nTheirsSchema : c->nOursSchema;
    SchemaEntry *aOther = side ? c->aOursSchema : c->aTheirsSchema;
    int nOther = side ? c->nOursSchema : c->nTheirsSchema;

    for(i=0; i<nNew; i++){
      if( !aNew[i].zType || strcmp(aNew[i].zType, "index")!=0 ) continue;
      if( !aNew[i].zName || !aNew[i].zSql || !aNew[i].zTblName ) continue;
      if( findSchemaEntry(c->aAncSchema, c->nAncSchema, aNew[i].zName) ){
        continue;
      }
      for(j=0; j<c->nAncSchema; j++){
        SchemaEntry *pOld = &c->aAncSchema[j];
        if( !pOld->zType || strcmp(pOld->zType, "index")!=0 ) continue;
        if( !pOld->zName || !pOld->zSql || !pOld->zTblName ) continue;
        if( sqlite3_stricmp(pOld->zTblName, aNew[i].zTblName)!=0 ) continue;
        /* A drop of the older index is a replacement, not a duplicate. */
        if( !findSchemaEntry(aNew, nNew, pOld->zName) ) continue;
        if( !findSchemaEntry(aOther, nOther, pOld->zName) ) continue;
        if( !mergeIndexSameKey(aNew[i].zSql, pOld->zSql) ) continue;
        if( c->pzErrMsg ){
          sqlite3_free(*c->pzErrMsg);
          *c->pzErrMsg = sqlite3_mprintf(
              "cannot merge: indexes '%s' and '%s' cover the same columns of "
              "table '%s'; drop one of them, then merge",
              aNew[i].zName, pOld->zName, aNew[i].zTblName);
        }
        return SQLITE_ERROR;
      }
    }
  }
  return SQLITE_OK;
}

/* Drop on one side, edit of that column on the other, in a shared
** row. Dolt reports a conflict; refuse rather than pick a winner. */
int mergePass1CheckRowEditOfDroppedColumn(MergePass1Ctx *c){
  int side, i, j;

  for(side=0; side<2; side++){
    SchemaEntry *aDrop = side ? c->aTheirsSchema : c->aOursSchema;
    int nDrop = side ? c->nTheirsSchema : c->nOursSchema;
    SchemaEntry *aEdit = side ? c->aOursSchema : c->aTheirsSchema;
    int nEdit = side ? c->nOursSchema : c->nTheirsSchema;
    struct TableEntry *aEditCat = side ? c->aOurs : c->aTheirs;
    int nEditCat = side ? c->nOurs : c->nTheirs;

    /* Replay: Dolt protects non-NULL live values; NULL or already-absent
    ** can drop. */
    if( !c->bBranchMerge && side==0 ) continue;

    for(i=0; i<c->nAncSchema; i++){
      const char *zTable = c->aAncSchema[i].zName;
      SchemaEntry *pDropSe;
      SchemaEntry *pEditSe;
      struct TableEntry *pAncCat;
      struct TableEntry *pEditCatEnt;
      ParsedColumn *aAncCols = 0;
      ParsedColumn *aDropCols = 0;
      int nAncCols = 0, nDropCols = 0;

      if( !zTable || !c->aAncSchema[i].zType ) continue;
      if( strcmp(c->aAncSchema[i].zType, "table")!=0 ) continue;
      pDropSe = findSchemaEntry(aDrop, nDrop, zTable);
      pEditSe = findSchemaEntry(aEdit, nEdit, zTable);
      if( !pDropSe || !pEditSe || !pDropSe->zSql || !pEditSe->zSql ) continue;
      /* Schema disagreement is judged by the schema merge. */
      if( strcmp(pEditSe->zSql, c->aAncSchema[i].zSql)!=0 ) continue;
      if( strcmp(pDropSe->zSql, c->aAncSchema[i].zSql)==0 ) continue;
      pAncCat = doltliteFindTableByName(c->aAnc, c->nAnc, zTable);
      pEditCatEnt = doltliteFindTableByName(aEditCat, nEditCat, zTable);
      if( !pAncCat || !pEditCatEnt ) continue;
      if( prollyHashCompare(&pAncCat->root, &pEditCatEnt->root)==0 ) continue;
      if( parseColumns(c->aAncSchema[i].zSql, &aAncCols, &nAncCols)!=SQLITE_OK ){
        continue;
      }
      if( parseColumns(pDropSe->zSql, &aDropCols, &nDropCols)!=SQLITE_OK ){
        freeColumns(aAncCols, nAncCols);
        continue;
      }
      for(j=0; j<nAncCols; j++){
        int bEdited = 0;
        int rc;
        if( parsedColumnIndexByName(aDropCols, nDropCols,
                                    aAncCols[j].zName)>=0 ){
          continue;
        }
        /* Rename, not drop. */
        if( j<nDropCols
         && parsedColumnIndexByName(aAncCols, nAncCols,
                                    aDropCols[j].zName)<0 ){
          continue;
        }
        rc = mergeRowEditsColumn(c->db, &pAncCat->root, &pEditCatEnt->root,
                                 pAncCat->flags, pEditCatEnt->flags,
                                 j, !c->bBranchMerge, &bEdited);
        if( rc!=SQLITE_OK ){
          freeColumns(aAncCols, nAncCols);
          freeColumns(aDropCols, nDropCols);
          return rc;
        }
        if( bEdited ){
          if( c->pzErrMsg ){
            sqlite3_free(*c->pzErrMsg);
            if( c->bBranchMerge ){
              *c->pzErrMsg = sqlite3_mprintf(
                  "cannot merge: column '%s' of table '%s' was dropped on one "
                  "branch and its value changed on the other; drop the column "
                  "on both branches, or revert the change, then merge",
                  aAncCols[j].zName, zTable);
            }else{
              *c->pzErrMsg = sqlite3_mprintf(
                  "cannot apply: column '%s' of table '%s' would be dropped, "
                  "discarding a changed value",
                  aAncCols[j].zName, zTable);
            }
          }
          freeColumns(aAncCols, nAncCols);
          freeColumns(aDropCols, nDropCols);
          return SQLITE_ERROR;
        }
      }
      freeColumns(aAncCols, nAncCols);
      freeColumns(aDropCols, nDropCols);
    }
  }
  return SQLITE_OK;
}

/* Identifier scan, quoted or bare (SQLite may quote). Indexes start
** at the column list so the index name cannot match. Over-matches by
** design: an expression index or view naming it breaks the same way. */
static int mergeSqlNamesColumn(const char *zSql, const char *zType,
                               const char *zColumn){
  const char *z;
  int nCol;

  if( !zSql || !zType || !zColumn || !zColumn[0] ) return 0;
  nCol = (int)strlen(zColumn);
  z = zSql;
  if( strcmp(zType, "index")==0 ){
    z = strchr(zSql, '(');
    if( !z ) return 0;
    z++;
  }
  while( *z ){
    const char *zTok;
    int nTok;
    if( *z=='"' || *z=='`' || *z=='[' || *z=='\'' ){
      char cEnd = *z=='[' ? ']' : *z;
      z++;
      zTok = z;
      while( *z && *z!=cEnd ) z++;
      nTok = (int)(z-zTok);
      if( *z ) z++;
    }else if( sqlite3Isalnum(*z) || *z=='_' || *z=='$' ){
      zTok = z;
      while( *z && (sqlite3Isalnum(*z) || *z=='_' || *z=='$') ) z++;
      nTok = (int)(z-zTok);
    }else{
      z++;
      continue;
    }
    if( nTok==nCol && sqlite3_strnicmp(zTok, zColumn, nCol)==0 ) return 1;
  }
  return 0;
}

static int mergeSideRenamedColumnTo(const char *zAncSql, const char *zSideSql,
                                    const char *zColumn, char **pzNew){
  ParsedColumn *aAnc = 0;
  ParsedColumn *aSide = 0;
  int nAnc = 0, nSide = 0, i, bRenamed = 0;

  if( pzNew ) *pzNew = 0;
  if( !zAncSql || !zSideSql ) return 0;
  if( parseColumns(zAncSql, &aAnc, &nAnc)!=SQLITE_OK ) return 0;
  if( parseColumns(zSideSql, &aSide, &nSide)!=SQLITE_OK ){
    freeColumns(aAnc, nAnc);
    return 0;
  }
  for(i=0; i<nAnc && i<nSide; i++){
    if( sqlite3_stricmp(aAnc[i].zName, zColumn)!=0 ) continue;
    if( sqlite3_stricmp(aSide[i].zName, aAnc[i].zName)==0 ) break;
    if( parsedColumnIndexByName(aSide, nSide, aAnc[i].zName)>=0 ) break;
    if( !parsedColumnDefinitionsMatch(&aSide[i], &aAnc[i]) ) break;
    bRenamed = 1;
    if( pzNew ) *pzNew = sqlite3_mprintf("%s", aSide[i].zName);
    break;
  }
  freeColumns(aAnc, nAnc);
  freeColumns(aSide, nSide);
  return bRenamed;
}

static int mergeSideRenamedColumn(const char *zAncSql, const char *zSideSql,
                                  const char *zColumn){
  return mergeSideRenamedColumnTo(zAncSql, zSideSql, zColumn, 0);
}

static int mergeSideRenamedAnyColumn(const char *zAncSql, const char *zSideSql){
  ParsedColumn *aAnc = 0;
  int nAnc = 0, i, bAny = 0;

  if( parseColumns(zAncSql, &aAnc, &nAnc)!=SQLITE_OK ) return 0;
  for(i=0; i<nAnc && !bAny; i++){
    if( mergeSideRenamedColumn(zAncSql, zSideSql, aAnc[i].zName) ) bAny = 1;
  }
  freeColumns(aAnc, nAnc);
  return bAny;
}

/* Dual column-rename plus a dependent that names a renamed column.
** Merged catalog takes the table from one side and the object from
** the other, so it cannot load. Dolt retargets the object; we refuse. */
int mergePass1CheckDependentOverDualRename(MergePass1Ctx *c){
  int side, i, j;

  for(side=0; side<2; side++){
    SchemaEntry *aDep = side ? c->aTheirsSchema : c->aOursSchema;
    int nDep = side ? c->nTheirsSchema : c->nOursSchema;
    SchemaEntry *aOther = side ? c->aOursSchema : c->aTheirsSchema;
    int nOther = side ? c->nOursSchema : c->nTheirsSchema;

    for(i=0; i<nDep; i++){
      SchemaEntry *pDep = &aDep[i];
      SchemaEntry *pAncTbl;
      SchemaEntry *pDepTbl;
      SchemaEntry *pOtherTbl;
      ParsedColumn *aAncCols = 0;
      int nAncCols = 0;

      if( !pDep->zType || !pDep->zSql || !pDep->zTblName ) continue;
      if( strcmp(pDep->zType, "table")==0 ) continue;
      pAncTbl = findSchemaEntry(c->aAncSchema, c->nAncSchema, pDep->zTblName);
      pDepTbl = findSchemaEntry(aDep, nDep, pDep->zTblName);
      pOtherTbl = findSchemaEntry(aOther, nOther, pDep->zTblName);
      if( !pAncTbl || !pDepTbl || !pOtherTbl ) continue;
      if( !pAncTbl->zSql || !pDepTbl->zSql || !pOtherTbl->zSql ) continue;
      /* One-sided rename already carries its objects across. */
      if( !mergeSideRenamedAnyColumn(pAncTbl->zSql, pOtherTbl->zSql) ) continue;
      if( !mergeSideRenamedAnyColumn(pAncTbl->zSql, pDepTbl->zSql) ) continue;
      /* Object sits beside the adopted table; only a cross-side pair
      ** breaks the catalog. */
      {
        char **azAdd = 0, **azDrop = 0, **azRen = 0;
        int nAdd = 0, nDrop = 0, nRen = 0, k;
        int choice = SCHEMA_MERGE_DEFAULT, resolved = 0, bLoser;
        char *zErr = 0;
        const char *zOursTblSql = side ? pOtherTbl->zSql : pDepTbl->zSql;
        const char *zTheirsTblSql = side ? pDepTbl->zSql : pOtherTbl->zSql;
        if( trySchemaColumnMerge(pAncTbl->zSql, zOursTblSql, zTheirsTblSql,
                                 &azAdd, &nAdd, &azDrop, &nDrop,
                                 &azRen, &nRen, &choice, &resolved,
                                 &zErr)!=SQLITE_OK ){
          choice = SCHEMA_MERGE_DEFAULT;
        }
        for(k=0; k<nAdd; k++) sqlite3_free(azAdd[k]);
        for(k=0; k<nDrop; k++) sqlite3_free(azDrop[k]);
        for(k=0; k<nRen; k++) sqlite3_free(azRen[k]);
        sqlite3_free(azAdd);
        sqlite3_free(azDrop);
        sqlite3_free(azRen);
        sqlite3_free(zErr);
        bLoser = side ? (choice==SCHEMA_MERGE_OURS)
                      : (choice==SCHEMA_MERGE_THEIRS);
        if( !bLoser ) continue;
      }
      if( parseColumns(pAncTbl->zSql, &aAncCols, &nAncCols)!=SQLITE_OK ){
        continue;
      }
      for(j=0; j<nAncCols; j++){
        const char *zCol = aAncCols[j].zName;
        char *zNew = 0;
        int bNames;
        if( !mergeSideRenamedColumnTo(pAncTbl->zSql, pDepTbl->zSql, zCol,
                                      &zNew) ){
          sqlite3_free(zNew);
          continue;
        }
        /* This side already rewrote the object to the new name. */
        bNames = zNew && mergeSqlNamesColumn(pDep->zSql, pDep->zType, zNew);
        sqlite3_free(zNew);
        if( !bNames ) continue;
        /* Dual rename of this column is judged elsewhere. */
        if( mergeSideRenamedColumn(pAncTbl->zSql, pOtherTbl->zSql, zCol) ){
          continue;
        }
        if( c->pzErrMsg ){
          sqlite3_free(*c->pzErrMsg);
          *c->pzErrMsg = sqlite3_mprintf(
              "cannot merge: %s '%s' covers column '%s' of table '%s', which "
              "one branch renamed while the other renamed another column of "
              "the same table; rename on one branch only, or drop the %s, "
              "then merge",
              pDep->zType, pDep->zName, zCol, pDep->zTblName, pDep->zType);
        }
        freeColumns(aAncCols, nAncCols);
        return SQLITE_ERROR;
      }
      freeColumns(aAncCols, nAncCols);
    }
  }
  return SQLITE_OK;
}

/* Trigger on a table the other side renamed or dropped. Triggers
** resolve at schema load, so a dangling one cannot be represented.
** Dolt keeps the old name; we refuse. Distinguish drop from rename. */
int mergePass1CheckTriggerOverRenamedTable(MergePass1Ctx *c){
  int side, i, j;

  for(side=0; side<2; side++){
    SchemaEntry *aTrig = side ? c->aTheirsSchema : c->aOursSchema;
    int nTrig = side ? c->nTheirsSchema : c->nOursSchema;
    SchemaEntry *aOther = side ? c->aOursSchema : c->aTheirsSchema;
    int nOther = side ? c->nOursSchema : c->nTheirsSchema;

    for(i=0; i<nTrig; i++){
      const char *zTable = aTrig[i].zTblName;
      int bRenamed = 0;
      if( !aTrig[i].zType || strcmp(aTrig[i].zType, "trigger")!=0 ) continue;
      if( !aTrig[i].zName || !zTable ) continue;
      /* Ancestor trigger already followed the rename; only one added
      ** beside the rename has nowhere to land. */
      if( findSchemaEntry(c->aAncSchema, c->nAncSchema, aTrig[i].zName) ){
        continue;
      }
      if( !findSchemaEntry(c->aAncSchema, c->nAncSchema, zTable) ) continue;
      if( findSchemaEntry(aOther, nOther, zTable) ) continue;
      /* Same columns as the ancestor table under a new name: rename,
      ** not drop. Names alone cannot tell them apart. */
      {
        SchemaEntry *pAncTbl = findSchemaEntry(c->aAncSchema, c->nAncSchema,
                                               zTable);
        ParsedColumn *aAncCols = 0;
        int nAncCols = 0;
        if( !pAncTbl || !pAncTbl->zSql ) continue;
        if( parseColumns(pAncTbl->zSql, &aAncCols, &nAncCols)!=SQLITE_OK ){
          continue;
        }
        for(j=0; j<nOther && !bRenamed; j++){
          ParsedColumn *aCand = 0;
          int nCand = 0, m, same;
          if( !aOther[j].zType || strcmp(aOther[j].zType, "table")!=0 ) continue;
          if( !aOther[j].zName || !aOther[j].zSql ) continue;
          if( findSchemaEntry(c->aAncSchema, c->nAncSchema, aOther[j].zName) ){
            continue;
          }
          if( parseColumns(aOther[j].zSql, &aCand, &nCand)!=SQLITE_OK ) continue;
          same = nCand==nAncCols;
          for(m=0; m<nCand && same; m++){
            if( sqlite3_stricmp(aCand[m].zName, aAncCols[m].zName)!=0
             || !parsedColumnDefinitionsMatch(&aCand[m], &aAncCols[m]) ){
              same = 0;
            }
          }
          freeColumns(aCand, nCand);
          if( same ) bRenamed = 1;
        }
        freeColumns(aAncCols, nAncCols);
      }
      /* Dropped, not renamed: the trigger follows its table out of the
      ** merge. MySQL drops triggers with their table; Dolt keeps an
      ** orphan no loadable catalog can hold (dolthub/dolt#11588). */
      if( !bRenamed ) continue;
      if( c->pzErrMsg ){
        sqlite3_free(*c->pzErrMsg);
        *c->pzErrMsg = sqlite3_mprintf(
            "cannot merge: trigger '%s' runs on table '%s', which the other "
            "branch renamed; drop or recreate the trigger, then merge",
            aTrig[i].zName, zTable);
      }
      return SQLITE_ERROR;
    }
  }
  return SQLITE_OK;
}

/* Index added over a column the other side renamed. Nothing retargets
** it, and the catalog cannot load. Dolt keeps the index; we refuse. */
int mergePass1CheckIndexOverRenamedColumn(MergePass1Ctx *c){
  int side, i;

  for(side=0; side<2; side++){
    SchemaEntry *aNew = side ? c->aTheirsSchema : c->aOursSchema;
    int nNew = side ? c->nTheirsSchema : c->nOursSchema;
    SchemaEntry *aOther = side ? c->aOursSchema : c->aTheirsSchema;
    int nOther = side ? c->nOursSchema : c->nTheirsSchema;

    for(i=0; i<nNew; i++){
      SchemaEntry *pAncTbl;
      SchemaEntry *pOtherTbl;
      char *zCol = 0;
      if( !aNew[i].zType || strcmp(aNew[i].zType, "index")!=0 ) continue;
      if( !aNew[i].zName || !aNew[i].zSql || !aNew[i].zTblName ) continue;
      if( findSchemaEntry(c->aAncSchema, c->nAncSchema, aNew[i].zName) ){
        continue;
      }
      if( findSchemaEntry(aOther, nOther, aNew[i].zName) ) continue;
      pAncTbl = findSchemaEntry(c->aAncSchema, c->nAncSchema, aNew[i].zTblName);
      pOtherTbl = findSchemaEntry(aOther, nOther, aNew[i].zTblName);
      if( !pAncTbl || !pOtherTbl ) continue;
      if( !mergeIndexColumnRenamedAway(aNew[i].zSql, pAncTbl->zSql,
                                       pOtherTbl->zSql, &zCol) ){
        continue;
      }
      if( c->pzErrMsg ){
        sqlite3_free(*c->pzErrMsg);
        *c->pzErrMsg = sqlite3_mprintf(
            "cannot merge: index '%s' covers column '%s' of table '%s', which "
            "the other branch renamed; drop or recreate the index, then merge",
            aNew[i].zName, zCol, aNew[i].zTblName);
      }
      sqlite3_free(zCol);
      return SQLITE_ERROR;
    }
  }
  return SQLITE_OK;
}

/* ================= dependents follow their table =================
**
** A table's dependents (indexes, triggers, views) are adopted per name,
** independently of the table, so a column rename on one side can pair an
** adopted table with a dependent that names a column it does not have,
** and the merged catalog cannot load. Dolt retargets the dependent.
**
** Rather than repairing the assembled catalog, subtract the rename from
** the merge's view of the world: rewrite the three schema arrays so the
** table and its dependents carry one baseline text on every side, equalize
** the table entries' schema hashes so pass1 sees the schema as unchanged,
** and queue the renames as post-load schema actions. ALTER TABLE RENAME
** COLUMN then rewrites the table and every dependent through SQLite's own
** machinery, and the post-action flush serializes the coherent result.
*/

/* Flat old,new rename pairs anc->side when the delta is pure renames:
** same column count, every definition matches its position, and no name
** moves to another position. Anything else (adds, drops, swaps, type
** changes) is not normalizable here. */
static int mergePureRenamePairs(
  const char *zAncSql,
  const char *zSideSql,
  char ***pazPairs, int *pnPairs,
  int *pbPure
){
  ParsedColumn *aAnc = 0, *aSide = 0;
  int nAnc = 0, nSide = 0, i, rc = SQLITE_OK;
  char **az = 0;
  int n = 0;

  *pazPairs = 0;
  *pnPairs = 0;
  *pbPure = 0;
  if( parseColumns(zAncSql, &aAnc, &nAnc)!=SQLITE_OK ) return SQLITE_OK;
  if( parseColumns(zSideSql, &aSide, &nSide)!=SQLITE_OK ){
    freeColumns(aAnc, nAnc);
    return SQLITE_OK;
  }
  if( nAnc!=nSide ) goto pure_done;
  for(i=0; i<nAnc; i++){
    if( !parsedColumnDefinitionsMatch(&aSide[i], &aAnc[i]) ) goto pure_done;
    if( sqlite3_stricmp(aAnc[i].zName, aSide[i].zName)==0 ) continue;
    if( parsedColumnIndexByName(aSide, nSide, aAnc[i].zName)>=0 ) goto pure_done;
    if( parsedColumnIndexByName(aAnc, nAnc, aSide[i].zName)>=0 ) goto pure_done;
    {
      char **azNew = sqlite3_realloc(az, (n+2)*(int)sizeof(char*));
      if( !azNew ){ rc = SQLITE_NOMEM; goto pure_done; }
      az = azNew;
      az[n] = sqlite3_mprintf("%s", aAnc[i].zName);
      az[n+1] = sqlite3_mprintf("%s", aSide[i].zName);
      if( !az[n] || !az[n+1] ){ n += 2; rc = SQLITE_NOMEM; goto pure_done; }
      n += 2;
    }
  }
  *pbPure = 1;
  *pazPairs = az;
  *pnPairs = n;
  az = 0;
  n = 0;
pure_done:
  freeAddedColumns(az, n);
  freeColumns(aAnc, nAnc);
  freeColumns(aSide, nSide);
  return rc;
}

static const char *mergeRenameMapLookup(char **az, int n, const char *zOld){
  int i;
  for(i=0; i+1<n; i+=2){
    if( sqlite3_stricmp(az[i], zOld)==0 ) return az[i+1];
  }
  return 0;
}

/* zSide is zAnc with side renames applied by SQLite's rewriter and nothing
** else: identical byte-for-byte outside identifier tokens, and each
** identifier either matches or maps old->new. */
static int mergeTextsEqualModuloRenames(
  const char *zAnc,
  const char *zSide,
  char **azPairs, int nPairs
){
  const char *a = zAnc;
  const char *s = zSide;

  if( !zAnc || !zSide ) return 0;
  while( *a || *s ){
    int aId = sqlite3Isalnum(*a) || *a=='_' || *a=='$' || *a=='"' || *a=='`' || *a=='[';
    int sId = sqlite3Isalnum(*s) || *s=='_' || *s=='$' || *s=='"' || *s=='`' || *s=='[';
    if( !aId || !sId ){
      if( *a!=*s ) return 0;
      if( *a==0 ) break;
      a++;
      s++;
      continue;
    }
    {
      const char *aTok, *sTok;
      int nATok, nSTok;
      if( *a=='"' || *a=='`' || *a=='[' ){
        char cEnd = *a=='[' ? ']' : *a;
        a++; aTok = a;
        while( *a && *a!=cEnd ) a++;
        nATok = (int)(a-aTok);
        if( *a ) a++;
      }else{
        aTok = a;
        while( sqlite3Isalnum(*a) || *a=='_' || *a=='$' ) a++;
        nATok = (int)(a-aTok);
      }
      if( *s=='"' || *s=='`' || *s=='[' ){
        char cEnd = *s=='[' ? ']' : *s;
        s++; sTok = s;
        while( *s && *s!=cEnd ) s++;
        nSTok = (int)(s-sTok);
        if( *s ) s++;
      }else{
        sTok = s;
        while( sqlite3Isalnum(*s) || *s=='_' || *s=='$' ) s++;
        nSTok = (int)(s-sTok);
      }
      if( nATok==nSTok && sqlite3_strnicmp(aTok, sTok, nATok)==0 ) continue;
      {
        int i;
        for(i=0; i+1<nPairs; i+=2){
          if( (int)strlen(azPairs[i])==nATok
           && sqlite3_strnicmp(azPairs[i], aTok, nATok)==0
           && (int)strlen(azPairs[i+1])==nSTok
           && sqlite3_strnicmp(azPairs[i+1], sTok, nSTok)==0 ){
            break;
          }
        }
        if( i+1>=nPairs ) return 0;
      }
    }
  }
  return 1;
}

static int mergeTableTextHasColumn(const char *zTblSql, const char *zName){
  ParsedColumn *aCols = 0;
  int nCols = 0, bHas;
  if( parseColumns(zTblSql, &aCols, &nCols)!=SQLITE_OK ) return 0;
  bHas = parsedColumnIndexByName(aCols, nCols, zName)>=0;
  freeColumns(aCols, nCols);
  return bHas;
}

/* Loadable against zTblSql: every rename-universe name the dependent's text
** mentions must be a column of that table text. Names outside the universe
** cannot have moved, so they are not checked. */
static int mergeDependentCoherent(
  const SchemaEntry *pDep,
  const char *zTblSql,
  char **azUniverse, int nUniverse
){
  int i;
  for(i=0; i<nUniverse; i++){
    if( !mergeSqlNamesColumn(pDep->zSql, pDep->zType, azUniverse[i]) ) continue;
    if( !mergeTableTextHasColumn(zTblSql, azUniverse[i]) ) return 0;
  }
  return 1;
}

static void mergeSetEntryText(SchemaEntry *pSe, const char *zSql){
  char *z = sqlite3_mprintf("%s", zSql);
  if( z ){
    sqlite3_free(pSe->zSql);
    pSe->zSql = z;
  }
}

/* zSql with every identifier token equal to zOld replaced by zNew, quoting
** style preserved. Everything outside identifier tokens is untouched. */
static char *mergeRewriteIdent(
  const char *zSql,
  const char *zOld,
  const char *zNew
){
  sqlite3_str *pOut = sqlite3_str_new(0);
  const char *z = zSql;
  int nOld = (int)strlen(zOld);

  while( *z ){
    if( *z=='"' || *z=='`' || *z=='[' ){
      char cOpen = *z;
      char cEnd = *z=='[' ? ']' : *z;
      const char *zTok;
      int nTok;
      z++;
      zTok = z;
      while( *z && *z!=cEnd ) z++;
      nTok = (int)(z-zTok);
      if( *z ) z++;
      if( nTok==nOld && sqlite3_strnicmp(zTok, zOld, nOld)==0 ){
        sqlite3_str_appendf(pOut, "%c%s%c", cOpen, zNew, cEnd);
      }else{
        sqlite3_str_appendf(pOut, "%c%.*s%c", cOpen, nTok, zTok, cEnd);
      }
    }else if( sqlite3Isalnum(*z) || *z=='_' || *z=='$' ){
      const char *zTok = z;
      int nTok;
      while( sqlite3Isalnum(*z) || *z=='_' || *z=='$' ) z++;
      nTok = (int)(z-zTok);
      if( nTok==nOld && sqlite3_strnicmp(zTok, zOld, nOld)==0 ){
        sqlite3_str_appendall(pOut, zNew);
      }else{
        sqlite3_str_append(pOut, zTok, nTok);
      }
    }else{
      sqlite3_str_appendchar(pOut, 1, *z);
      z++;
    }
  }
  return sqlite3_str_finish(pOut);
}

static int mergeRecordTableRename(
  SchemaMergeAction **ppActions,
  int *pnActions,
  const char *zOld,
  const char *zNew
){
  SchemaMergeAction *aNew;
  aNew = sqlite3_realloc(*ppActions,
                         (*pnActions+1)*(int)sizeof(SchemaMergeAction));
  if( !aNew ) return SQLITE_NOMEM;
  *ppActions = aNew;
  memset(&aNew[*pnActions], 0, sizeof(SchemaMergeAction));
  aNew[*pnActions].zTableName = sqlite3_mprintf("%s", zOld);
  aNew[*pnActions].zRenameTable = sqlite3_mprintf("%s", zNew);
  if( !aNew[*pnActions].zTableName || !aNew[*pnActions].zRenameTable ){
    return SQLITE_NOMEM;
  }
  (*pnActions)++;
  return SQLITE_OK;
}

/* One side renamed a table the other side put a trigger on. Un-rename the
** table in that side's arrays and queue ALTER TABLE RENAME TO instead, so
** the trigger lands on a table the catalog has, and the post-load rename
** carries it — and every other dependent — to the new name. Dolt instead
** keeps an orphaned trigger no loadable catalog can hold and that rebinds
** to any future table with the old name (dolthub/dolt#11588); following
** the table is a deliberate divergence. */
static int mergePreNormalizeTableRename(
  struct TableEntry *aAnc, int nAnc,
  struct TableEntry *aOurs, int nOurs,
  struct TableEntry *aTheirs, int nTheirs,
  SchemaEntry *aAncSchema, int nAncSchema,
  SchemaEntry *aOursSchema, int nOursSchema,
  SchemaEntry *aTheirsSchema, int nTheirsSchema,
  SchemaMergeAction **ppActions, int *pnActions
){
  int side, t, i, rc = SQLITE_OK;

  for(side=0; side<2; side++){
    SchemaEntry *aSide = side ? aTheirsSchema : aOursSchema;
    int nSide = side ? nTheirsSchema : nOursSchema;
    SchemaEntry *aOther = side ? aOursSchema : aTheirsSchema;
    int nOther = side ? nOursSchema : nTheirsSchema;
    struct TableEntry *aSideEnt = side ? aTheirs : aOurs;
    int nSideEnt = side ? nTheirs : nOurs;

    for(t=0; t<nAncSchema; t++){
      SchemaEntry *pAncT = &aAncSchema[t];
      SchemaEntry *pNewT = 0;
      char *azPair[2];
      int nCand = 0;

      if( !pAncT->zType || strcmp(pAncT->zType, "table")!=0 ) continue;
      if( !pAncT->zName || !pAncT->zSql ) continue;
      if( findSchemaEntry(aSide, nSide, pAncT->zName) ) continue;
      /* The other side must still hold the table under its old name. */
      if( !findSchemaEntry(aOther, nOther, pAncT->zName) ) continue;

      /* Exactly one new table whose text is the ancestor's under a new
      ** name is a rename; anything else stays a drop plus a create. */
      for(i=0; i<nSide; i++){
        char *azProbe[2];
        if( !aSide[i].zType || strcmp(aSide[i].zType, "table")!=0 ) continue;
        if( !aSide[i].zName || !aSide[i].zSql ) continue;
        if( findSchemaEntry(aAncSchema, nAncSchema, aSide[i].zName) ) continue;
        azProbe[0] = pAncT->zName;
        azProbe[1] = aSide[i].zName;
        if( !mergeTextsEqualModuloRenames(pAncT->zSql, aSide[i].zSql,
                                          azProbe, 2) ){
          continue;
        }
        pNewT = &aSide[i];
        nCand++;
      }
      if( nCand!=1 || !pNewT ) continue;
      if( findSchemaEntry(aOther, nOther, pNewT->zName) ) continue;

      /* The pairing must be bijective. If the new table's text also matches
      ** another ancestor table this side no longer has, tables with equal
      ** column lists make the rename ambiguous — a dropped table could be
      ** claimed by an unrelated rename — so it stays a drop plus a create. */
      {
        int bAmbiguous = 0;
        for(i=0; i<nAncSchema && !bAmbiguous; i++){
          char *azProbe[2];
          SchemaEntry *pOtherAnc = &aAncSchema[i];
          if( pOtherAnc==pAncT ) continue;
          if( !pOtherAnc->zType || strcmp(pOtherAnc->zType, "table")!=0 ) continue;
          if( !pOtherAnc->zName || !pOtherAnc->zSql ) continue;
          if( findSchemaEntry(aSide, nSide, pOtherAnc->zName) ) continue;
          azProbe[0] = pOtherAnc->zName;
          azProbe[1] = pNewT->zName;
          if( mergeTextsEqualModuloRenames(pOtherAnc->zSql, pNewT->zSql,
                                           azProbe, 2) ){
            bAmbiguous = 1;
          }
        }
        if( bAmbiguous ) continue;
      }

      azPair[0] = pAncT->zName;
      azPair[1] = pNewT->zName;

      /* Un-rename the side's dependents first, while the new name still
      ** identifies them. Ancestor text when the change is mechanical,
      ** a token rewrite when the dependent was created after the rename. */
      for(i=0; i<nSide; i++){
        SchemaEntry *pDep = &aSide[i];
        SchemaEntry *pDepAnc;
        if( pDep==pNewT || !pDep->zType || !pDep->zName ) continue;
        if( strcmp(pDep->zType, "table")==0 ) continue;
        if( !pDep->zTblName
         || sqlite3_stricmp(pDep->zTblName, pNewT->zName)!=0 ){
          /* Views name themselves; catch ones shadow-rewritten to the
          ** new table name by content. */
          if( strcmp(pDep->zType, "view")!=0 || !pDep->zSql
           || !mergeSqlNamesColumn(pDep->zSql, pDep->zType, pNewT->zName) ){
            continue;
          }
        }
        pDepAnc = findSchemaEntry(aAncSchema, nAncSchema, pDep->zName);
        if( pDepAnc && pDepAnc->zSql && pDep->zSql
         && mergeTextsEqualModuloRenames(pDepAnc->zSql, pDep->zSql,
                                         azPair, 2) ){
          mergeSetEntryText(pDep, pDepAnc->zSql);
        }else if( pDep->zSql ){
          char *z = mergeRewriteIdent(pDep->zSql, pNewT->zName, pAncT->zName);
          if( !z ) return SQLITE_NOMEM;
          sqlite3_free(pDep->zSql);
          pDep->zSql = z;
        }
        if( pDep->zTblName
         && sqlite3_stricmp(pDep->zTblName, pNewT->zName)==0 ){
          char *z = sqlite3_mprintf("%s", pAncT->zName);
          if( !z ) return SQLITE_NOMEM;
          sqlite3_free(pDep->zTblName);
          pDep->zTblName = z;
        }
      }

      /* Queue the replay before renaming the row, while both names are
      ** still in hand. */
      rc = mergeRecordTableRename(ppActions, pnActions,
                                  pAncT->zName, pNewT->zName);
      if( rc!=SQLITE_OK ) return rc;

      /* The side's catalog entry follows the row back to the old name. */
      {
        struct TableEntry *pEnt =
            doltliteFindTableByName(aSideEnt, nSideEnt, pNewT->zName);
        struct TableEntry *pEntAnc =
            doltliteFindTableByName(aAnc, nAnc, pAncT->zName);
        if( pEnt ){
          char *z = sqlite3_mprintf("%s", pAncT->zName);
          if( !z ) return SQLITE_NOMEM;
          sqlite3_free(pEnt->zName);
          pEnt->zName = z;
          if( pEntAnc ) pEnt->schemaHash = pEntAnc->schemaHash;
        }
      }
      {
        char *z1 = sqlite3_mprintf("%s", pAncT->zName);
        char *z2 = sqlite3_mprintf("%s", pAncT->zName);
        if( !z1 || !z2 ){
          sqlite3_free(z1);
          sqlite3_free(z2);
          return SQLITE_NOMEM;
        }
        sqlite3_free(pNewT->zName);
        pNewT->zName = z1;
        sqlite3_free(pNewT->zTblName);
        pNewT->zTblName = z2;
        mergeSetEntryText(pNewT, pAncT->zSql);
      }
    }
  }
  return rc;
}

/* A dependent of zTbl surviving into the merge, or a view whose cross-side
** texts are the mechanical shadow of these renames. Views carry their own
** name in zTblName, so they qualify by shape rather than by parent. */
static int mergeCollectDependent(
  const char *zTbl,
  SchemaEntry *pAnc, SchemaEntry *pOurs, SchemaEntry *pTheirs,
  char **azRenO, int nRenO,
  char **azRenT, int nRenT,
  int *pbMechanical
){
  SchemaEntry *pAny = pOurs ? pOurs : (pTheirs ? pTheirs : pAnc);

  *pbMechanical = 0;
  if( !pAny || !pAny->zType || !pAny->zSql ) return 0;
  if( strcmp(pAny->zType, "index")==0 || strcmp(pAny->zType, "trigger")==0 ){
    if( !pAny->zTblName || sqlite3_stricmp(pAny->zTblName, zTbl)!=0 ) return 0;
  }else if( strcmp(pAny->zType, "view")!=0 ){
    return 0;
  }
  /* Dropped on a side: it does not survive, so it constrains nothing. */
  if( pAnc && (!pOurs || !pTheirs) ) return 0;
  if( pAnc ){
    if( !pAnc->zSql || !pOurs->zSql || !pTheirs->zSql ) return 0;
    if( !mergeTextsEqualModuloRenames(pAnc->zSql, pOurs->zSql, azRenO, nRenO) ){
      return -1;
    }
    if( !mergeTextsEqualModuloRenames(pAnc->zSql, pTheirs->zSql, azRenT, nRenT) ){
      return -1;
    }
    *pbMechanical = 1;
  }
  return 1;
}

int mergePreNormalizeRenamedDependents(
  struct TableEntry *aAnc, int nAnc,
  struct TableEntry *aOurs, int nOurs,
  struct TableEntry *aTheirs, int nTheirs,
  SchemaEntry *aAncSchema, int nAncSchema,
  SchemaEntry *aOursSchema, int nOursSchema,
  SchemaEntry *aTheirsSchema, int nTheirsSchema,
  SchemaMergeAction **ppActions, int *pnActions
){
  int t, i, rc = SQLITE_OK;

  rc = mergePreNormalizeTableRename(aAnc, nAnc, aOurs, nOurs,
                                    aTheirs, nTheirs,
                                    aAncSchema, nAncSchema,
                                    aOursSchema, nOursSchema,
                                    aTheirsSchema, nTheirsSchema,
                                    ppActions, pnActions);
  if( rc!=SQLITE_OK ) return rc;

  for(t=0; t<nAncSchema; t++){
    SchemaEntry *pAncT = &aAncSchema[t];
    SchemaEntry *pOurT, *pTheirT;
    char **azRenO = 0, **azRenT = 0, **azUni = 0;
    int nRenO = 0, nRenT = 0, nUni = 0;
    int bPureO = 0, bPureT = 0;
    const char *zBase = 0;
    int bBaseOurs = 0, bBaseTheirs = 0;
    int bBail;

    if( !pAncT->zType || strcmp(pAncT->zType, "table")!=0 ) continue;
    if( !pAncT->zName || !pAncT->zSql ) continue;
    pOurT = findSchemaEntry(aOursSchema, nOursSchema, pAncT->zName);
    pTheirT = findSchemaEntry(aTheirsSchema, nTheirsSchema, pAncT->zName);
    if( !pOurT || !pTheirT || !pOurT->zSql || !pTheirT->zSql ) continue;

    rc = mergePureRenamePairs(pAncT->zSql, pOurT->zSql, &azRenO, &nRenO, &bPureO);
    if( rc==SQLITE_OK ){
      rc = mergePureRenamePairs(pAncT->zSql, pTheirT->zSql, &azRenT, &nRenT, &bPureT);
    }
    if( rc!=SQLITE_OK ) goto table_done;
    if( !bPureO || !bPureT || (nRenO==0 && nRenT==0) ) goto table_done;
    /* The same ancestor column renamed on both sides is a real conflict
    ** (different names) or already coherent (same name); leave both. */
    for(i=0; i+1<nRenO; i+=2){
      if( mergeRenameMapLookup(azRenT, nRenT, azRenO[i]) ) goto table_done;
    }

    /* Old and new names of every rename: the only identifiers whose
    ** presence can differ between the three table texts. */
    azUni = sqlite3_malloc((nRenO+nRenT)*(int)sizeof(char*));
    if( !azUni ){ rc = SQLITE_NOMEM; goto table_done; }
    for(i=0; i<nRenO; i++) azUni[nUni++] = azRenO[i];
    for(i=0; i<nRenT; i++) azUni[nUni++] = azRenT[i];

    /* Baseline candidates, ancestor first: the text every surviving
    ** dependent can load against. */
    {
      const char *azCand[3];
      int c;
      azCand[0] = pAncT->zSql;
      azCand[1] = pOurT->zSql;
      azCand[2] = pTheirT->zSql;
      zBase = 0;
      bBail = 0;
      for(c=0; c<3 && !bBail; c++){
        int bOk = 1;
        for(i=0; i<nOursSchema+nTheirsSchema && bOk && !bBail; i++){
          SchemaEntry *pSide = i<nOursSchema ? &aOursSchema[i]
                                             : &aTheirsSchema[i-nOursSchema];
          SchemaEntry *pDepAnc, *pDepOurs, *pDepTheirs, *pPick;
          int bMech = 0, q;
          if( !pSide->zName ) continue;
          /* Each dependent once: ours' array wins when present on both. */
          if( i>=nOursSchema
           && findSchemaEntry(aOursSchema, nOursSchema, pSide->zName) ){
            continue;
          }
          pDepAnc = findSchemaEntry(aAncSchema, nAncSchema, pSide->zName);
          pDepOurs = findSchemaEntry(aOursSchema, nOursSchema, pSide->zName);
          pDepTheirs = findSchemaEntry(aTheirsSchema, nTheirsSchema, pSide->zName);
          if( pDepAnc==pAncT ) continue;
          q = mergeCollectDependent(pAncT->zName, pDepAnc, pDepOurs, pDepTheirs,
                                    azRenO, nRenO, azRenT, nRenT, &bMech);
          if( q<0 ){
            /* Materially edited beside a rename: only a problem if it
            ** names a renamed column, then no baseline is safe. */
            SchemaEntry *pDep = pDepOurs ? pDepOurs : pDepTheirs;
            int u;
            for(u=0; u<nUni; u++){
              if( mergeSqlNamesColumn(pDep->zSql, pDep->zType, azUni[u]) ){
                bBail = 1;
                break;
              }
            }
            continue;
          }
          if( q==0 ) continue;
          if( bMech ){
            /* Mechanical shadow: the version from the baseline's own side
            ** is coherent with it by construction. */
            continue;
          }
          /* New on one side: its only text must load against the baseline. */
          pPick = pDepOurs ? pDepOurs : pDepTheirs;
          if( !mergeDependentCoherent(pPick, azCand[c], azUni, nUni) ){
            bOk = 0;
          }
        }
        if( bBail ) break;
        if( bOk && c==0 ){
          /* Everything loads against the ancestor text; but is everything
          ** also coherent with the text the merge would adopt today? Probe
          ** the adopted side: with renames on it, an old-name dependent
          ** cannot load, so normalization is still required. */
          int bAdoptedIncoherent = 0;
          const char *zAdopted = 0;
          int oursChanged = strcmp(pAncT->zSql, pOurT->zSql)!=0;
          int theirsChanged = strcmp(pAncT->zSql, pTheirT->zSql)!=0;
          if( oursChanged && theirsChanged ){
            char **azA=0, **azD=0, **azR=0;
            int nA=0, nD=0, nR=0, choice=SCHEMA_MERGE_DEFAULT, res=0;
            char *zErr = 0;
            if( trySchemaColumnMerge(pAncT->zSql, pOurT->zSql, pTheirT->zSql,
                                     &azA, &nA, &azD, &nD, &azR, &nR,
                                     &choice, &res, &zErr)==SQLITE_OK ){
              zAdopted = choice==SCHEMA_MERGE_THEIRS ? pTheirT->zSql
                                                     : pOurT->zSql;
            }
            sqlite3_free(zErr);
            freeAddedColumns(azA, nA);
            freeAddedColumns(azD, nD);
            freeAddedColumns(azR, nR);
          }else{
            zAdopted = oursChanged ? pOurT->zSql : pTheirT->zSql;
          }
          if( zAdopted ){
            for(i=0; i<nOursSchema+nTheirsSchema && !bAdoptedIncoherent; i++){
              SchemaEntry *pSide = i<nOursSchema ? &aOursSchema[i]
                                                 : &aTheirsSchema[i-nOursSchema];
              SchemaEntry *pDepAnc, *pDepOurs, *pDepTheirs, *pPick;
              int bMech = 0, q;
              if( !pSide->zName ) continue;
              if( i>=nOursSchema
               && findSchemaEntry(aOursSchema, nOursSchema, pSide->zName) ){
                continue;
              }
              pDepAnc = findSchemaEntry(aAncSchema, nAncSchema, pSide->zName);
              pDepOurs = findSchemaEntry(aOursSchema, nOursSchema, pSide->zName);
              pDepTheirs = findSchemaEntry(aTheirsSchema, nTheirsSchema,
                                           pSide->zName);
              if( pDepAnc==pAncT ) continue;
              q = mergeCollectDependent(pAncT->zName, pDepAnc, pDepOurs,
                                        pDepTheirs, azRenO, nRenO,
                                        azRenT, nRenT, &bMech);
              if( q<=0 ) continue;
              /* Today's adoption: the side that changed it, ours on ties. */
              if( pDepAnc ){
                int chO = pDepOurs && strcmp(pDepAnc->zSql, pDepOurs->zSql)!=0;
                int chT = pDepTheirs && strcmp(pDepAnc->zSql, pDepTheirs->zSql)!=0;
                pPick = chT && !chO ? pDepTheirs : pDepOurs;
              }else{
                pPick = pDepOurs ? pDepOurs : pDepTheirs;
              }
              if( pPick && !mergeDependentCoherent(pPick, zAdopted, azUni, nUni) ){
                bAdoptedIncoherent = 1;
              }
            }
          }
          if( !bAdoptedIncoherent ){
            /* Today's merge already loads; do not disturb it. */
            goto table_done;
          }
        }
        if( bOk ){
          zBase = azCand[c];
          bBaseOurs = (c==1);
          bBaseTheirs = (c==2);
          break;
        }
      }
      if( bBail || !zBase ) goto table_done;
    }

    /* Queue the renames the baseline still needs before mutating any text
    ** they are derived from. */
    {
      char **azQ = 0;
      int nQ = 0, k;
      char **azFromO = bBaseOurs ? 0 : azRenO;
      int nFromO = bBaseOurs ? 0 : nRenO;
      char **azFromT = bBaseTheirs ? 0 : azRenT;
      int nFromT = bBaseTheirs ? 0 : nRenT;
      azQ = sqlite3_malloc((nFromO+nFromT)*(int)sizeof(char*)+1);
      if( !azQ ){ rc = SQLITE_NOMEM; goto table_done; }
      for(k=0; k<nFromO; k++) azQ[nQ++] = sqlite3_mprintf("%s", azFromO[k]);
      for(k=0; k<nFromT; k++) azQ[nQ++] = sqlite3_mprintf("%s", azFromT[k]);
      for(k=0; k<nQ; k++){
        if( !azQ[k] ){ freeAddedColumns(azQ, nQ); rc = SQLITE_NOMEM; goto table_done; }
      }
      if( nQ>0 ){
        /* The action owns azQ from here. */
        rc = recordSchemaColumnChanges(ppActions, pnActions, pAncT->zName,
                                       0, 0, 0, 0, azQ, nQ);
        if( rc!=SQLITE_OK ){ freeAddedColumns(azQ, nQ); goto table_done; }
      }else{
        sqlite3_free(azQ);
      }
    }

    /* One baseline text on every side: the merge no longer sees a schema
    ** change on this table or its shadowed dependents. zBase aliases one of
    ** the entries about to be rewritten, so it needs its own copy first. */
    {
      char *zBaseOwned = sqlite3_mprintf("%s", zBase);
      if( !zBaseOwned ){ rc = SQLITE_NOMEM; goto table_done; }
      mergeSetEntryText(pAncT, zBaseOwned);
      mergeSetEntryText(pOurT, zBaseOwned);
      mergeSetEntryText(pTheirT, zBaseOwned);
      sqlite3_free(zBaseOwned);
    }
    for(i=0; i<nOursSchema+nTheirsSchema; i++){
      SchemaEntry *pSide = i<nOursSchema ? &aOursSchema[i]
                                         : &aTheirsSchema[i-nOursSchema];
      SchemaEntry *pDepAnc, *pDepOurs, *pDepTheirs, *pFrom;
      char *zDepOwned;
      int bMech = 0, q;
      if( !pSide->zName ) continue;
      if( i>=nOursSchema
       && findSchemaEntry(aOursSchema, nOursSchema, pSide->zName) ){
        continue;
      }
      pDepAnc = findSchemaEntry(aAncSchema, nAncSchema, pSide->zName);
      pDepOurs = findSchemaEntry(aOursSchema, nOursSchema, pSide->zName);
      pDepTheirs = findSchemaEntry(aTheirsSchema, nTheirsSchema, pSide->zName);
      if( pDepAnc==pAncT ) continue;
      q = mergeCollectDependent(pAncT->zName, pDepAnc, pDepOurs, pDepTheirs,
                                azRenO, nRenO, azRenT, nRenT, &bMech);
      if( q<=0 || !bMech ) continue;
      pFrom = bBaseOurs ? pDepOurs : (bBaseTheirs ? pDepTheirs : pDepAnc);
      if( !pFrom || !pFrom->zSql ) continue;
      zDepOwned = sqlite3_mprintf("%s", pFrom->zSql);
      if( !zDepOwned ){ rc = SQLITE_NOMEM; goto table_done; }
      mergeSetEntryText(pDepAnc, zDepOwned);
      mergeSetEntryText(pDepOurs, zDepOwned);
      mergeSetEntryText(pDepTheirs, zDepOwned);
      sqlite3_free(zDepOwned);
    }
    {
      struct TableEntry *pEntAnc =
          doltliteFindTableByName(aAnc, nAnc, pAncT->zName);
      struct TableEntry *pEntOurs =
          doltliteFindTableByName(aOurs, nOurs, pAncT->zName);
      struct TableEntry *pEntTheirs =
          doltliteFindTableByName(aTheirs, nTheirs, pAncT->zName);
      struct TableEntry *pEntBase = bBaseOurs ? pEntOurs
                                  : (bBaseTheirs ? pEntTheirs : pEntAnc);
      if( pEntAnc && pEntOurs && pEntTheirs && pEntBase ){
        pEntAnc->schemaHash = pEntBase->schemaHash;
        pEntOurs->schemaHash = pEntBase->schemaHash;
        pEntTheirs->schemaHash = pEntBase->schemaHash;
      }
    }

table_done:
    freeAddedColumns(azRenO, nRenO);
    freeAddedColumns(azRenT, nRenT);
    sqlite3_free(azUni);
    if( rc!=SQLITE_OK ) return rc;
  }
  return SQLITE_OK;
}

#endif /* DOLTLITE_PROLLY */

